INSERT INTO `ec_products_translations` VALUES ('ar',58,'11 11 إيلين','<p class= style=text-align:right; data-start=151 data-end=496>عطر ساحر وغامض ينبض بنفحات العنبر والزهور البيضاء. تتفتح أزهار الياسمين المشعة على قاعدة كريمية من العنبر الدافئ وخشب الكشمير، مانحة العطر طابعًا أنثويًا قويًا لا يُنسى.<br><strong data-start=345 data-end=361>عائلة العطر:</strong> عنبري زهري<br><strong data-start=375 data-end=389>نوع العطر:</strong> زهري دافئ<br><strong data-start=402 data-end=424 data-is-only-node=>المكونات الأساسية:</strong> الياسمين، العنبر، خشب الكشمير<br><strong data-start=457 data-end=467>النوع:</strong> عطر (EDP)<br><strong data-start=480 data-end=490>الحجم:</strong> 50 مل</p><h2 class= style=text-align:right; data-start=498 data-end=515>&nbsp;</h2>',''),('ar',59,'11 11 آنجلز','<p style=text-align:right;>عطر فاخر دافئ ينبض بأحاسيس ناعمة وغنية. يبدأ بنفحة الكونياك المميزة، يليها مزيج سلس من التونكا، القرفة، والبلوط، وتستقر القاعدة على الفانيليا واللوز المكرمل وخشب الصندل، لتغمر الحواس بدفء أنيق لا يُقاوم.<br><strong>عائلة العطر:</strong> عنبري فانيلي<br><strong>نوع العطر:</strong> شرقي دافئ<br><strong>المكونات الأساسية:</strong> الكونياك، التونكا، القرفة، البلوط، الفانيليا، اللوز المكرمل، خشب الصندل<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p><h2 style=text-align:right;>&nbsp;</h2>',''),('ar',60,'11 11 أفغانو','<p style=text-align:right;>عطر غامض وعميق يأسر الحواس بنفحاته الداكنة والدخانية. يمزج بين الأخشاب الغنية، الأعشاب العطرية، ولمسة من القنب والبخور، ليمنحك تجربة جريئة ومتفردة لا تُنسى.<br><strong>عائلة العطر:</strong> خشبي عطري<br><strong>نوع العطر:</strong> داكن وغامض<br><strong>المكونات الأساسية:</strong> القنب، البخور، العود، الأخشاب، الأعشاب العطرية<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p><h2 style=text-align:right;>&nbsp;</h2>',''),('ar',61,'11 11 أبسولو','<p class= style=text-align:right; data-start=132 data-end=543>عطر أنيق ومنعش يعكس القوة والثقة. يتألق بمزيج نابض من الأناناس والبرغموت، يتوازن مع لمسات من الفلفل الوردي والزنجبيل، ويستقر على قاعدة راقية من الأخشاب والمسك والعنبر، ليمنحك حضوراً عصريًا وجذابًا.<br><strong data-start=354 data-end=370>عائلة العطر:</strong> حمضي خشبي<br><strong data-start=383 data-end=397>نوع العطر:</strong> فاكهي منعش<br><strong data-start=411 data-end=433 data-is-only-node=>المكونات الأساسية:</strong> الأناناس، البرغموت، الفلفل الوردي، الزنجبيل، الأخشاب، المسك، العنبر<br><strong data-start=504 data-end=514>النوع:</strong> عطر (EDP)<br><strong data-start=527 data-end=537>الحجم:</strong> 50 مل</p><h2 class= style=text-align:right; data-start=545 data-end=562>&nbsp;</h2>',''),('ar',62,'11 11 أفنتوس','<p class= style=text-align:right; data-start=129 data-end=541>عطر أيقوني يجمع بين الانتعاش والقوة بأسلوب راقٍ وجذاب. يفتتح بنفحات مشرقة من الأناناس والبرغموت، يليها قلب من البتولا والياسمين، وتستقر القاعدة على المسك والطحالب والعنبر، لتُبرز حضورك بثقة وأناقة.<br><strong data-start=351 data-end=367>عائلة العطر:</strong> حمضي فاكهي<br><strong data-start=381 data-end=395>نوع العطر:</strong> فاكهي خشبي<br><strong data-start=409 data-end=431 data-is-only-node=>المكونات الأساسية:</strong> الأناناس، البرغموت، البتولا، الياسمين، المسك، طحلب السنديان، العنبر<br><strong data-start=502 data-end=512>النوع:</strong> عطر (EDP)<br><strong data-start=525 data-end=535>الحجم:</strong> 50 مل</p><h2 class= style=text-align:right; data-start=543 data-end=561>&nbsp;</h2>',''),('ar',63,'11 11 أكوا','<p class= style=text-align:right; data-start=131 data-end=515>عطر منعش ونقي مستوحى من قوة البحر ونسمات الطبيعة. تتناغم فيه الحمضيات الزاهية مع لمسات الأزهار والمريمية، وتستقر على قاعدة من الأخشاب والمسك، ليمنحك إحساسًا دائمًا بالانتعاش والصفاء.<br><strong data-start=338 data-end=354>عائلة العطر:</strong> حمضي بحري<br><strong data-start=367 data-end=381>نوع العطر:</strong> منعش ونظيف<br><strong data-start=395 data-end=417 data-is-only-node=>المكونات الأساسية:</strong> الليمون، البرغموت، الياسمين، المريمية، خشب الأرز، المسك<br><strong data-start=476 data-end=486>النوع:</strong> عطر (EDP)<br><strong data-start=499 data-end=509>الحجم:</strong> 50 مل</p><h2 class= style=text-align:right; data-start=517 data-end=532>&nbsp;</h2>',''),('ar',64,'11 11 ألتاير','<p class= style=text-align:right; data-start=141 data-end=533>عطر فاخر ودافئ ينبض بحلاوة راقية. تبدأ تركيبته بنفحات مشرقة من البرغموت والقرفة، يرافقها قلب غني بالفانيليا والمسك، وتكتمل بقاعدة ناعمة من العنبر وخشب الغاياك، ليمنحك حضورًا أنيقًا وجذابًا.<br><strong data-start=355 data-end=371>عائلة العطر:</strong> شرقي فانيلي<br><strong data-start=386 data-end=400>نوع العطر:</strong> دافئ وحلو<br><strong data-start=413 data-end=435 data-is-only-node=>المكونات الأساسية:</strong> البرغموت، القرفة، الفانيليا، المسك، العنبر، خشب الغاياك<br><strong data-start=494 data-end=504>النوع:</strong> عطر (EDP)<br><strong data-start=517 data-end=527>الحجم:</strong> 50 مل</p><h2 class= style=text-align:right; data-start=535 data-end=553>&nbsp;</h2>',''),('ar',65,'11 11 بلو','<p class= style=text-align:right; data-start=590 data-end=923>عطر منعش وأنيق يمزج بين الحمضيات الحيوية، والأعشاب العطرية، والنفحات الخشبية الدافئة. هذا العطر الخالد يجسد الثقة والأناقة، مثالي لكل المناسبات.<br><strong data-start=759 data-end=775>عائلة العطر:</strong> خشبي عطري<br><strong data-start=788 data-end=802>نوع العطر:</strong> منعش وأنيق<br><strong data-start=816 data-end=838>المكونات الأساسية:</strong> الحمضيات، الأعشاب العطرية، النفحات الخشبية<br><strong data-start=884 data-end=894>النوع:</strong> عطر (EDP)<br><strong data-start=907 data-end=917>الحجم:</strong> 50 مل</p>',''),('ar',66,'11 11 إيروس','<p class= style=text-align:right; data-start=514 data-end=915>عطر جريء ومليء بالحيوية يحتفي بالقوة والجاذبية. يمتزج فيه النعناع والتفاح الأخضر المنعش مع دفء التونكا والفانيليا، ويستقر على قاعدة من خشب الأرز وطحلب السنديان ليوفر هالة ذكورية آسرة.<br><strong data-start=722 data-end=738>عائلة العطر:</strong> شرقي منعش<br><strong data-start=751 data-end=765>نوع العطر:</strong> عطري حلو<br><strong data-start=777 data-end=799>المكونات الأساسية:</strong> النعناع، التفاح الأخضر، حبوب التونكا، الفانيليا، خشب الأرز، طحلب السنديان<br><strong data-start=876 data-end=886>النوع:</strong> عطر (EDP)<br><strong data-start=899 data-end=909>الحجم:</strong> 50 مل</p>',''),('ar',67,'11 11 جنتلمان','<p class= style=text-align:right; data-start=836 data-end=1338>عطر قوي وأنيق يبدأ بنفحات من الفلفل الأسود، الخزامى، والبرغموت. في القلب، يمتزج السوسن مع القرنفل والقرفة ليضفي دفئًا وعمقًا. وتستقر القاعدة على مزيج ناعم من فانيليا سوداء، التونكا، البنزوين، الباتشولي، وبلسم التولو لتوقيع ذكوري جذاب.<br><strong data-start=1095 data-end=1111>عائلة العطر:</strong> خشبي عطري<br><strong data-start=1124 data-end=1138>نوع العطر:</strong> دافئ وتابلي<br><strong data-start=1153 data-end=1175>المكونات الأساسية:</strong> الفلفل الأسود، الخزامى، البرغموت، السوسن، القرنفل، القرفة، فانيليا سوداء، حبوب التونكا، البنزوين، الباتشولي، بلسم التولو<br><strong data-start=1299 data-end=1309>النوع:</strong> عطر (EDP)<br><strong data-start=1322 data-end=1332>الحجم:</strong> 50 مل</p>',''),('ar',68,'11 11 جلتي','<p class=\"\" style=\"text-align:right;\" data-start=\"649\" data-end=\"1024\">عطر عصري وجذاب يمزج بين الانتعاش والدفء الحسي. يبدأ بنفحات منعشة من الليمون والخزامى، يليه قلب من زهر البرتقال، وتستقر القاعدة على خشب الأرز والباتشولي لتوقيع رجولي مميز وواثق.<br><strong data-start=\"850\" data-end=\"866\">عائلة العطر:</strong> عطري خشبي<br><strong data-start=\"879\" data-end=\"893\">نوع العطر:</strong> منعش ودافئ<br><strong data-start=\"907\" data-end=\"929\">المكونات الأساسية:</strong> الليمون، الخزامى، زهر البرتقال، خشب الأرز، الباتشولي<br><strong data-start=\"985\" data-end=\"995\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1008\" data-end=\"1018\">الحجم:</strong> 50 مل</p>',NULL),('ar',69,'11 11 إصفهان','<p style=\"text-align:right;\">عطر شرقي فاخر وأنيق يمزج بين العود الدخاني والورد الغني. تنطلق رائحته بنفحات عميقة من الورد، تتوازن مع اللابدانوم والباتشولي، وتستقر على قاعدة دافئة من العود وخشب الصندل لترك أثر ملكي يدوم طويلًا.<br><strong>عائلة العطر:</strong> شرقي خشبي<br><strong>نوع العطر:</strong> عود وزهري<br><strong>المكونات الأساسية:</strong> الورد، اللابدانوم، الباتشولي، العود، خشب الصندل<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',70,'11 11 لورد','<p class=\"\" style=\"text-align:right;\" data-start=\"639\" data-end=\"1031\">عطر نبيل وراقٍ يجسد الأناقة والقوة الهادئة. يبدأ بنفحة دافئة من البراندي، يتبعها عبير كريم الحلاقة وحبوب التونكا، وتستقر القاعدة على لمسات ناعمة من العنبر والنفحات الخشبية لتوقيع كلاسيكي فاخر.<br><strong data-start=\"856\" data-end=\"872\">عائلة العطر:</strong> شرقي خشبي<br><strong data-start=\"885\" data-end=\"899\">نوع العطر:</strong> دافئ وراقي<br><strong data-start=\"913\" data-end=\"935\">المكونات الأساسية:</strong> البراندي، كريم الحلاقة، حبوب التونكا، العنبر، الأخشاب<br><strong data-start=\"992\" data-end=\"1002\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1015\" data-end=\"1025\">الحجم:</strong> 50 مل</p>',NULL),('ar',71,'11 11 مليون','<p class=\"\" style=\"text-align:right;\" data-start=\"640\" data-end=\"1041\">عطر جريء ولا يقاوم ينبض بالطاقة والجاذبية. يفتتح بنفحات منعشة من الجريب فروت والقرفة، يتبعها قلب من الورد والجلد، وتستقر القاعدة على العنبر والباتشولي والنفحات الخشبية لتوقيع رجولي مغرٍ وواثق.<br><strong data-start=\"857\" data-end=\"873\">عائلة العطر:</strong> شرقي تابلي<br><strong data-start=\"887\" data-end=\"901\">نوع العطر:</strong> دافئ وجذاب<br><strong data-start=\"915\" data-end=\"937\">المكونات الأساسية:</strong> الجريب فروت، القرفة، الورد، الجلد، العنبر، الباتشولي، الأخشاب<br><strong data-start=\"1002\" data-end=\"1012\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1025\" data-end=\"1035\">الحجم:</strong> 50 مل</p>',NULL),('ar',72,'11 11 ماي سيلف','<p style=\"text-align:right;\">عطر عصري ونابض بالحياة يجمع بين الانتعاش والحسية النظيفة. يبدأ ببرغموت كالابريا المتألق، يتبعه قلب من زهر البرتقال، ويستقر على قاعدة دافئة من أمبروفيكس™ ونفحات خشبية ناعمة لتوقيع عصري وأنيق.<br><strong>عائلة العطر:</strong> خشبي زهري<br><strong>نوع العطر:</strong> منعش ونظيف<br><strong>المكونات الأساسية:</strong> برغموت كالابريا، زهر البرتقال، أمبروفيكس™، نفحات خشبية<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p><hr><p>&nbsp;</p>',NULL),('ar',73,'11 11 نوماد','<p style=\"text-align:right;\">عطر غني وجريء يجسد روح المغامرة والاكتشاف. تنطلق رائحته بالزعفران الدافئ والفلفل الأسود، يتبعها قلب من العود والكاكاو، وتستقر على قاعدة عميقة من الجلد والعنبر لتوقيع رجولي مميز وآسر.<br><strong>عائلة العطر:</strong> شرقي خشبي<br><strong>نوع العطر:</strong> دافئ وتابلي<br><strong>المكونات الأساسية:</strong> الزعفران، الفلفل الأسود، العود، الكاكاو، الجلد، العنبر<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',74,'11 11 أوركيد','<p class=\"\" style=\"text-align:right;\" data-start=\"634\" data-end=\"1052\">عطر فاخر وجريء بطابع داكن وحسي. يبدأ بنفحات غنية من الترفاس والكشمش الأسود، يليه قلب من الأوركيد الأسود والتوابل الغامضة. وتستقر القاعدة على الباتشولي، البخور، والفانيليا لترك أثر عميق لا يُنسى.<br><strong data-start=\"853\" data-end=\"869\">عائلة العطر:</strong> شرقي زهري<br><strong data-start=\"882\" data-end=\"896\">نوع العطر:</strong> داكن وحسي<br><strong data-start=\"909\" data-end=\"931\">المكونات الأساسية:</strong> الترفاس، الكشمش الأسود، الأوركيد الأسود، التوابل، الباتشولي، البخور، الفانيليا<br><strong data-start=\"1013\" data-end=\"1023\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1036\" data-end=\"1046\">الحجم:</strong> 50 مل</p>',NULL),('ar',75,'11 11 بريستيج','<p style=\"text-align:right;\">عطر قوي ومعقد يجمع بين النفحات الدخانية، الراتنجات الغنية، والتوابل العميقة مع قاعدة خشبية داكنة. يبدأ بالأوريجانو، البرغموت، وتوت البيمنتو، يليه قلب من العنبر، البخور، والأوبوبوناكس، ويستقر على الجلد، العود، والباتشولي لترك انطباع جريء ولا يُنسى.<br><strong>عائلة العطر:</strong> شرقي خشبي<br><strong>نوع العطر:</strong> دافئ ودخاني<br><strong>المكونات الأساسية:</strong> الأوريجانو، البرغموت، توت البيمنتو، العنبر، البخور، الأوبوبوناكس، الجلد، العود، الباتشولي<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',76,'11 11 روج','<p class=\"\" data-start=\"633\" data-end=\"1019\">عطر أيقوني مشرق يوازن بين الحلاوة والدفء الخشبي. يبدأ بالزعفران والياسمين، يليه قلب متوهج من العنبر وخشب العنبر، ويستقر على قاعدة من الراتنج وخشب الأرز لتوقيع جذاب لا يُنسى.<br><strong data-start=\"831\" data-end=\"847\">عائلة العطر:</strong> عنبري زهري<br><strong data-start=\"861\" data-end=\"875\">نوع العطر:</strong> حلو وخشبي<br><strong data-start=\"888\" data-end=\"910\">المكونات الأساسية:</strong> الزعفران، الياسمين، خشب العنبر، العنبر الرمادي، الراتنج، خشب الأرز<br><strong data-start=\"980\" data-end=\"990\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1003\" data-end=\"1013\">الحجم:</strong> 50 مل</p>',NULL),('ar',77,'11 11 سوفاج','<p class=\"\" style=\"text-align:right;\" data-start=\"643\" data-end=\"1055\">عطر جريء ومنعش يجسد الرجولة المطلقة والحرية. يبدأ بالفلفل الحار والبرغموت، يليه قلب من الخزامى والغرانيوم، وتستقر القاعدة على الباتشولي، نجيل الهند، والأمبروكسان لترك أثر قوي يدوم طويلاً.<br><strong data-start=\"855\" data-end=\"871\">عائلة العطر:</strong> أروماتيك فوجير<br><strong data-start=\"889\" data-end=\"903\">نوع العطر:</strong> منعش وتابلي<br><strong data-start=\"918\" data-end=\"940\">المكونات الأساسية:</strong> البرغموت، الفلفل، الخزامى، الغرانيوم، الباتشولي، نجيل الهند، الأمبروكسان<br><strong data-start=\"1016\" data-end=\"1026\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1039\" data-end=\"1049\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"1062\" data-end=\"1178\">&nbsp;</p>',NULL),('ar',78,'11 11 سيلفر','<p class=\"\" style=\"text-align:right;\" data-start=\"670\" data-end=\"1092\">عطر منعش ونقي مستوحى من هواء الجبال النقي وجداول المياه الباردة. يبدأ ببرغموت ويوسفي نابضين بالحيوية، يليه قلب من الشاي الأخضر والكشمش الأسود، وتستقر القاعدة على المسك وخشب الصندل لتوقيع عصري ومنعش يدوم طويلًا.<br><strong data-start=\"905\" data-end=\"921\">عائلة العطر:</strong> حمضي عطري<br><strong data-start=\"934\" data-end=\"948\">نوع العطر:</strong> منعش ونظيف<br><strong data-start=\"962\" data-end=\"984\">المكونات الأساسية:</strong> البرغموت، اليوسفي، الشاي الأخضر، الكشمش الأسود، المسك، خشب الصندل<br><strong data-start=\"1053\" data-end=\"1063\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1076\" data-end=\"1086\">الحجم:</strong> 50 مل</p>',NULL),('ar',79,'11 11 توباكو','<p class=\"\" style=\"text-align:right;\" data-start=\"669\" data-end=\"1109\">عطر دافئ وفاخر يجمع بين التبغ الحلو والفانيليا الكريمية والتوابل الغنية. يبدأ بتوابل مكثفة وأوراق التبغ، يليه قلب من التونكا والكاكاو، وتستقر القاعدة على الفواكه المجففة والنفحات الخشبية لترك عبير جذاب وغني يلف الحواس.<br><strong data-start=\"912\" data-end=\"928\">عائلة العطر:</strong> شرقي تابلي<br><strong data-start=\"942\" data-end=\"956\">نوع العطر:</strong> دافئ وحلو<br><strong data-start=\"969\" data-end=\"991\">المكونات الأساسية:</strong> أوراق التبغ، التوابل، الفانيليا، التونكا، الكاكاو، الفواكه المجففة، الأخشاب<br><strong data-start=\"1070\" data-end=\"1080\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1093\" data-end=\"1103\">الحجم:</strong> 50 مل</p>',NULL),('ar',80,'11 11 تايغر','<p class=\"\" style=\"text-align:right;\" data-start=\"632\" data-end=\"1042\">عطر مشرق ونابض بالحيوية يجسد التوازن بين الحمضيات المنعشة والعنبر الدافئ. يفتتح بالجريب فروت المتألق، يليه قلب أنيق من الزنجبيل والأمبروكسان، وتستقر القاعدة على نفحات خشبية وعنبرية ناعمة تعكس القوة والأناقة.<br><strong data-start=\"864\" data-end=\"880\">عائلة العطر:</strong> حمضي عنبري<br><strong data-start=\"894\" data-end=\"908\">نوع العطر:</strong> منعش ودافئ<br><strong data-start=\"922\" data-end=\"944\">المكونات الأساسية:</strong> الجريب فروت، الزنجبيل، الأمبروكسان، نوتات خشبية، العنبر<br><strong data-start=\"1003\" data-end=\"1013\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1026\" data-end=\"1036\">الحجم:</strong> 50 مل</p>',NULL),('ar',81,'11 11 وومو','<p class=\"\" style=\"text-align:right;\" data-start=\"631\" data-end=\"1000\">عطر جذاب وعصري يجمع بين الجرأة والرقي. يبدأ بالفانيليا الحيوية واللافاندين المنعش، يليه قلب من الميرمية، وتستقر القاعدة على نجيل الهند والعنبر لتوقيع ذكوري قوي وكاريزمي.<br><strong data-start=\"825\" data-end=\"841\">عائلة العطر:</strong> عنبري فوجير<br><strong data-start=\"856\" data-end=\"870\">نوع العطر:</strong> دافئ وعطري<br><strong data-start=\"884\" data-end=\"906\">المكونات الأساسية:</strong> الفانيليا، اللافاندين، الميرمية، نجيل الهند، العنبر<br><strong data-start=\"961\" data-end=\"971\">النوع:</strong> عطر (EDP)<br><strong data-start=\"984\" data-end=\"994\">الحجم:</strong> 50 مل</p>',NULL),('ar',82,'11 11 واي','<p style=\"text-align:right;\">عطر منعش وعصري يجسد روح الإبداع والثقة. يبدأ بالتفاح والبرغموت المنعشين، يليه قلب من الميرمية وإبرة الراعي، وتستقر القاعدة على خشب العنبر والتونكا لتوقيع رجولي نظيف وأنيق.<br><strong>عائلة العطر:</strong> أروماتيك فوجير<br><strong>نوع العطر:</strong> منعش وخشبي<br><strong>المكونات الأساسية:</strong> التفاح، البرغموت، الميرمية، إبرة الراعي، خشب العنبر، حبوب التونكا<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p><hr><p>&nbsp;</p>',NULL),('ar',83,'11 11 يو','<p style=\"text-align:right;\">عطر دافئ وجذاب ينبض بالحيوية والسحر. يفتتح بلمسات حارة من الهيل والفلفل الوردي، يليه قلب من الميرمية والبطيخ، وتستقر القاعدة على الكستناء، الفانيليا، وخشب العنبر لترك أثر عصري وملفت.<br><strong>عائلة العطر:</strong> شرقي فوجير<br><strong>نوع العطر:</strong> دافئ وتابلي<br><strong>المكونات الأساسية:</strong> الهيل، الفلفل الوردي، الميرمية، البطيخ، الكستناء، الفانيليا، خشب العنبر<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',84,'11 11 أدور','<p class=\"\" style=\"text-align:right;\" data-start=\"617\" data-end=\"1009\">عطر مشرق وأنثوي يحتفي بالأناقة الزهرية. يبدأ بنفحات منعشة من البرغموت والكمثرى، يتوسطه قلب غني من الياسمين، الورد، والإيلنغ، وتستقر القاعدة على المسك وخشب الأرز لتوقيع راقٍ وزمني لا يُنسى.<br><strong data-start=\"830\" data-end=\"846\">عائلة العطر:</strong> زهري<br><strong data-start=\"854\" data-end=\"868\">نوع العطر:</strong> أنثوي ومشرق<br><strong data-start=\"883\" data-end=\"905\">المكونات الأساسية:</strong> البرغموت، الكمثرى، الياسمين، الورد، الإيلنغ، المسك، خشب الأرز<br><strong data-start=\"970\" data-end=\"980\">النوع:</strong> عطر (EDP)<br><strong data-start=\"993\" data-end=\"1003\">الحجم:</strong> 50 مل</p>',NULL),('ar',85,'11 11 بيل','<p class=\"\" style=\"text-align:right;\" data-start=\"675\" data-end=\"1140\">عطر مشرق ومبهج يعكس الأناقة والسعادة. يبدأ بنفحات شهية من الكمثرى والكشمش الأسود، يليه قلب زهري من السوسن، الياسمين، وزهر البرتقال، وتستقر القاعدة على الفانيليا، البرالين، التونكا، والباتشولي لتوقيع أنثوي ناعم ومميز.<br><strong data-start=\"916\" data-end=\"932\">عائلة العطر:</strong> زهري غورماند<br><strong data-start=\"948\" data-end=\"962\">نوع العطر:</strong> حلو وأنيق<br><strong data-start=\"975\" data-end=\"997\">المكونات الأساسية:</strong> الكمثرى، الكشمش الأسود، السوسن، الياسمين، زهر البرتقال، الفانيليا، البرالين، حبوب التونكا، الباتشولي<br><strong data-start=\"1101\" data-end=\"1111\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1124\" data-end=\"1134\">الحجم:</strong> 50 مل</p>',NULL),('ar',86,'11 11 تشيري','<p class=\"\" style=\"text-align:right;\" data-start=\"661\" data-end=\"1066\">عطر غني ومغرٍ يجمع بين حلاوة الكرز ونفحاته الدافئة والجذابة. يبدأ بالكرز الناضج واللوز المر، يليه قلب من الورد والياسمين، وتستقر القاعدة على التونكا، بلسم بيرو، ونجيل الهند لعطر آسر لا يُنسى.<br><strong data-start=\"877\" data-end=\"893\">عائلة العطر:</strong> شرقي غورماند<br><strong data-start=\"909\" data-end=\"923\">نوع العطر:</strong> حلو وحسي<br><strong data-start=\"935\" data-end=\"957\">المكونات الأساسية:</strong> الكرز، اللوز المر، الورد، الياسمين، التونكا، بلسم بيرو، نجيل الهند<br><strong data-start=\"1027\" data-end=\"1037\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1050\" data-end=\"1060\">الحجم:</strong> 50 مل&nbsp;</p>',NULL),('ar',87,'11 11 كوكو','<p class=\"\" style=\"text-align:right;\" data-start=\"668\" data-end=\"1087\">عطر كلاسيكي أنثوي يجسد الأناقة والدفء. يبدأ بالماندرين والكزبرة المنعشة، يليه قلب زهري من الورد، الياسمين، وزهر البرتقال، وتستقر القاعدة على الباتشولي، التونكا، وخشب الصندل لتوقيع فاخر وعميق.<br><strong data-start=\"884\" data-end=\"900\">عائلة العطر:</strong> شرقي زهري<br><strong data-start=\"913\" data-end=\"927\">نوع العطر:</strong> دافئ وراقي<br><strong data-start=\"941\" data-end=\"963\">المكونات الأساسية:</strong> الماندرين، الكزبرة، الورد، الياسمين، زهر البرتقال، الباتشولي، التونكا، خشب الصندل<br><strong data-start=\"1048\" data-end=\"1058\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1071\" data-end=\"1081\">الحجم:</strong> 50 مل</p>',NULL),('ar',88,'11 11 فور هير','<p class=\"\" style=\"text-align:right;\" data-start=\"605\" data-end=\"941\">عطر ناعم وحسي يحتفي بالأنوثة برقي. يبدأ بنفحات زهرية من الورد والخوخ، يليه قلب غني بالمسك، وتستقر القاعدة على العنبر والباتشولي لتوقيع أنثوي ناعم وعميق.<br><strong data-start=\"782\" data-end=\"798\">عائلة العطر:</strong> زهري مسكي<br><strong data-start=\"811\" data-end=\"825\">نوع العطر:</strong> ناعم وحسي<br><strong data-start=\"838\" data-end=\"860\">المكونات الأساسية:</strong> الورد، الخوخ، المسك، العنبر، الباتشولي<br><strong data-start=\"902\" data-end=\"912\">النوع:</strong> عطر (EDP)<br><strong data-start=\"925\" data-end=\"935\">الحجم:</strong> 50 مل</p>',NULL),('ar',89,'11 11 جولد','<p style=\"text-align:right;\">عطر فاخر ومشرق يحتفي بالأنوثة الجريئة. يبدأ بنفحات عصيرية من الرمان، يتوسطه قلب مشع من الزهور البيضاء، وتستقر القاعدة على لمسات كريمية وخشبية لتوقيع أنثوي أنيق لا يُنسى.<br><strong>عائلة العطر:</strong> زهري فاكهي شيبر<br><strong>نوع العطر:</strong> جريء وأنثوي<br><strong>المكونات الأساسية:</strong> الرمان، الزهور البيضاء، نوتات كريمية وخشبية<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',90,'11 11 جود غيرل','<p style=\"text-align:right;\">عطر جريء وراقي يلعب على التناقضات. يبدأ باللوز والقهوة الحلوة، يتوسطه قلب زهري غني من الياسمين والتوبروز، وتستقر القاعدة على التونكا، الفانيليا، والكاكاو لتوقيع أنثوي مغرٍ ولا يُنسى.<br><strong>عائلة العطر:</strong> شرقي زهري<br><strong>نوع العطر:</strong> حلو وجريء<br><strong>المكونات الأساسية:</strong> اللوز، القهوة، الياسمين، التوبروز، التونكا، الفانيليا، الكاكاو<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',91,'11 11 هير','<p class=\"\" style=\"text-align:right;\" data-start=\"629\" data-end=\"1036\">عطر شبابي ومليء بالحيوية يجسد روح الحرية والمغامرة. يبدأ بتوليفة مشرقة من التوت الأحمر والكشمش الأسود، يتوسطه قلب زهري من البنفسج والياسمين، وتستقر القاعدة على المسك والعنبر لتوقيع أنثوي مشرق ولافت.<br><strong data-start=\"852\" data-end=\"868\">عائلة العطر:</strong> فاكهي زهري<br><strong data-start=\"882\" data-end=\"896\">نوع العطر:</strong> مشرق وجذاب<br><strong data-start=\"910\" data-end=\"932\">المكونات الأساسية:</strong> التوت الأحمر، الكشمش الأسود، البنفسج، الياسمين، المسك، العنبر<br><strong data-start=\"997\" data-end=\"1007\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1020\" data-end=\"1030\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"1043\" data-end=\"1145\">&nbsp;</p>',NULL),('ar',92,'11 11 أيدول','<p style=\"text-align:right;\">عطر ناعم ومفعم بالأنوثة يعكس القوة والنقاء. يبدأ بالكمثرى والبرغموت المنعشين، يتوسطه قلب مشرق من الورد والياسمين، وتستقر القاعدة على المسك الأبيض والفانيليا لتوقيع أنثوي راقٍ ومضيء.<br><strong>عائلة العطر:</strong> زهري<br><strong>نوع العطر:</strong> ناعم ومشرق<br><strong>المكونات الأساسية:</strong> الكمثرى، البرغموت، الورد، الياسمين، المسك الأبيض، الفانيليا<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',93,'11 11 لينتردي','<p style=\"text-align:right;\">عطر جريء وأنيق يتحدى التقاليد بأسلوب أنثوي مميز. يبدأ بزهر البرتقال المشرق، يليه قلب غني من الياسمين والتوبروز، وتستقر القاعدة على نجيل الهند والباتشولي لتوقيع يجمع بين النعومة والعمق.<br><strong>عائلة العطر:</strong> زهري خشبي<br><strong>نوع العطر:</strong> جريء وأنثوي<br><strong>المكونات الأساسية:</strong> زهر البرتقال، الياسمين، التوبروز، نجيل الهند، الباتشولي<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',94,'11 11 لو لوكس','<p class=\"\" style=\"text-align:right;\" data-start=\"631\" data-end=\"1021\">عطر مشرق وراقي يجسد الأناقة الخالدة. يبدأ بزهر البرتقال المتألق، يليه قلب غني من الياسمين والعسل، وتستقر القاعدة على الباتشولي وخشب الأرز مع لمسة من الورد لتوقيع أنثوي فاخر يدوم طويلاً.<br><strong data-start=\"841\" data-end=\"857\">عائلة العطر:</strong> زهري شرقي<br><strong data-start=\"870\" data-end=\"884\">نوع العطر:</strong> راقٍ ومضيء<br><strong data-start=\"898\" data-end=\"920\">المكونات الأساسية:</strong> زهر البرتقال، الياسمين، العسل، الباتشولي، خشب الأرز، الورد<br><strong data-start=\"982\" data-end=\"992\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1005\" data-end=\"1015\">الحجم:</strong> 50 مل</p>',NULL),('ar',95,'11 11 ليبر','<p style=\"text-align:right;\">عطر أنثوي وجريء يجمع بين الأناقة الزهرية والدفء الحسي. يبدأ بالماندرين المتألق والخزامى، يليه قلب من زهر البرتقال والياسمين، وتستقر القاعدة على الفانيليا والعنبر والمسك لتوقيع قوي وراقي.<br><strong>عائلة العطر:</strong> زهري<br><strong>نوع العطر:</strong> زهري دافئ<br><strong>المكونات الأساسية:</strong> الماندرين، الخزامى، زهر البرتقال، الياسمين، الفانيليا، العنبر، المسك<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',96,'11 11 Lina','<p>A romantic and addictive fragrance that blends freshness with a soft, powdery allure. It opens with bright lychee, rhubarb, and bergamot, blossoms into a heart of rose and peony, and settles into a velvety base of vanilla, musk, and cashmeran for a truly feminine signature.<br><strong>Fragrance Family:</strong> Floral<br><strong>Scent Type:</strong> Fresh & Powdery<br><strong>Key Ingredients:</strong> Lychee, Rhubarb, Bergamot, Rose, Peony, Vanilla, Musk, Cashmeran<br><strong>Type:</strong> Eau de Parfum (EDP)<br><strong>Size:</strong> 50ml</p>',''),('ar',97,'11 11 لينا','<p class=\"\" data-start=\"658\" data-end=\"1087\">عطر رومانسي وآسر يجمع بين الانتعاش والرقة البودَرية. يبدأ بلمسات مشرقة من الليتشي، الراوند، والبرغموت، يتوسطه قلب ناعم من الورد والفاوانيا، وتستقر القاعدة على الفانيليا، المسك، والكاشميرين لتوقيع أنثوي جذاب وراقٍ.<br><strong data-start=\"896\" data-end=\"912\">عائلة العطر:</strong> زهري<br><strong data-start=\"920\" data-end=\"934\">نوع العطر:</strong> ناعم ومنعش<br><strong data-start=\"948\" data-end=\"970\">المكونات الأساسية:</strong> الليتشي، الراوند، البرغموت، الورد، الفاوانيا، الفانيليا، المسك، الكاشميرين<br><strong data-start=\"1048\" data-end=\"1058\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1071\" data-end=\"1081\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"1094\" data-end=\"1181\">&nbsp;</p>',NULL),('ar',98,'11 11 ميس','<p class=\"\" style=\"text-align:right;\" data-start=\"610\" data-end=\"981\">عطر ناعم ومبهج يحتفي بالحب والأنوثة. يبدأ بالفاوانيا وزنابق الوادي المنعشة، يليه قلب رومانسي من الورد والسوسن، وتستقر القاعدة على المسك والفانيليا لتوقيع أنثوي راقٍ وزمني.<br><strong data-start=\"806\" data-end=\"822\">عائلة العطر:</strong> زهري<br><strong data-start=\"830\" data-end=\"844\">نوع العطر:</strong> رومانسي وناعم<br><strong data-start=\"861\" data-end=\"883\">المكونات الأساسية:</strong> الفاوانيا، زنبق الوادي، الورد، السوسن، المسك، الفانيليا<br><strong data-start=\"942\" data-end=\"952\">النوع:</strong> عطر (EDP)<br><strong data-start=\"965\" data-end=\"975\">الحجم:</strong> 50 مل</p>',NULL),('ar',99,'11 11 ماي واي','<p class=\"\" style=\"text-align:right;\" data-start=\"670\" data-end=\"1087\">عطر مشرق ومنعش يحتفي بالاكتشاف والارتباط. يبدأ بزهر البرتقال والبرغموت المشرقين، يليه قلب زهري من التوبروز والياسمين، وتستقر القاعدة على خشب الأرز، الفانيليا، والمسك الأبيض لتوقيع أنثوي عصري وأنيق.<br><strong data-start=\"892\" data-end=\"908\">عائلة العطر:</strong> زهري<br><strong data-start=\"916\" data-end=\"930\">نوع العطر:</strong> مشرق ومنعش<br><strong data-start=\"944\" data-end=\"966\">المكونات الأساسية:</strong> زهر البرتقال، البرغموت، التوبروز، الياسمين، خشب الأرز، الفانيليا، المسك الأبيض<br><strong data-start=\"1048\" data-end=\"1058\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1071\" data-end=\"1081\">الحجم:</strong> 50 مل</p>',NULL),('ar',100,'11 11 نمبر 5','<p class=\"\" style=\"text-align:right;\" data-start=\"665\" data-end=\"1099\">عطر أيقوني وخالد يجسد الأنوثة الكلاسيكية. يبدأ بالألدهيدات المنعشة والإيلنغ وزهر البرتقال، يليه قلب زهري من الياسمين والورد، وتستقر القاعدة على خشب الصندل والفانيليا ونجيل الهند لتوقيع راقٍ وزمني.<br><strong data-start=\"886\" data-end=\"902\">عائلة العطر:</strong> زهري ألدهيدي<br><strong data-start=\"918\" data-end=\"932\">نوع العطر:</strong> كلاسيكي وأنيق<br><strong data-start=\"949\" data-end=\"971\">المكونات الأساسية:</strong> الألدهيدات، الإيلنغ، زهر البرتقال، الياسمين، الورد، خشب الصندل، الفانيليا، نجيل الهند<br><strong data-start=\"1060\" data-end=\"1070\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1083\" data-end=\"1093\">الحجم:</strong> 50 مل</p>',NULL),('ar',101,'11 11 نوار','<p class=\"\" style=\"text-align:right;\" data-start=\"661\" data-end=\"1063\">عطر غامض وآسر يجمع بين عمق الأخشاب وغنى الأزهار الداكنة. يبدأ بالكشمش الأسود ونفحات مائية، يتوسطه قلب من الياسمين والنرجس، وتستقر القاعدة على العود، الباتشولي، والبخور لتوقيع أنيق وجذاب يدوم طويلاً.<br><strong data-start=\"884\" data-end=\"900\">عائلة العطر:</strong> خشبي زهري<br><strong data-start=\"913\" data-end=\"927\">نوع العطر:</strong> داكن وأنيق<br><strong data-start=\"941\" data-end=\"963\">المكونات الأساسية:</strong> الكشمش الأسود، الياسمين، النرجس، العود، الباتشولي، البخور<br><strong data-start=\"1024\" data-end=\"1034\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1047\" data-end=\"1057\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"1070\" data-end=\"1153\">&nbsp;</p>',NULL),('ar',102,'11 11 أوبـيـوم','<p class=\"\" style=\"text-align:right;\" data-start=\"689\" data-end=\"1143\">عطر مغرٍ ومليء بالطاقة يجمع بين القهوة الداكنة والفانيليا الحلوة مع لمسات زهرية مشرقة. يبدأ بالإجاص والفلفل الوردي، يليه قلب من زهر البرتقال والقهوة، وتستقر القاعدة على الفانيليا، الباتشولي، وخشب الأرز لتوقيع أنثوي جريء لا يُقاوم.<br><strong data-start=\"944\" data-end=\"960\">عائلة العطر:</strong> شرقي غورماند<br><strong data-start=\"976\" data-end=\"990\">نوع العطر:</strong> حلو وحسي<br><strong data-start=\"1002\" data-end=\"1024\">المكونات الأساسية:</strong> الإجاص، الفلفل الوردي، زهر البرتقال، القهوة، الفانيليا، الباتشولي، خشب الأرز<br><strong data-start=\"1104\" data-end=\"1114\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1127\" data-end=\"1137\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"1150\" data-end=\"1239\">&nbsp;</p>',NULL),('ar',103,'11 11 برادايز','<p style=\"text-align:right;\">عطر غني وساحر يجسد جمال الحدائق الاستوائية. يبدأ بالإجاص الأخضر العصير، يليه قلب مشرق من الياسمين والسوسن، وتستقر القاعدة على الفانيليا والعنبر لتوقيع أنثوي حسي وآسر.<br><strong>عائلة العطر:</strong> زهري فاكهي<br><strong>نوع العطر:</strong> استوائي وأنثوي<br><strong>المكونات الأساسية:</strong> الإجاص الأخضر، الياسمين، السوسن، الفانيليا، العنبر<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',104,'11 11 ريد أوبـيـوم','<p class=\"\" style=\"text-align:right;\" data-start=\"723\" data-end=\"1150\">عطر جريء وجذاب يعيد ابتكار الحسية بلمسة فاكهية آسرة. يبدأ بتوليفة شهية من الكرز والفلفل الوردي، يتوسطه قلب من الياسمين وزهر البرتقال، وتستقر القاعدة على القهوة، الفانيليا، والنفحات الخشبية لعطر حسي لا يُنسى.<br><strong data-start=\"955\" data-end=\"971\">عائلة العطر:</strong> فاكهي شرقي<br><strong data-start=\"985\" data-end=\"999\">نوع العطر:</strong> حلو وتابلي<br><strong data-start=\"1013\" data-end=\"1035\">المكونات الأساسية:</strong> الكرز، الفلفل الوردي، الياسمين، زهر البرتقال، القهوة، الفانيليا، الأخشاب<br><strong data-start=\"1111\" data-end=\"1121\">النوع:</strong> عطر (EDP)<br><strong data-start=\"1134\" data-end=\"1144\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"1157\" data-end=\"1253\">&nbsp;</p>',NULL),('ar',105,'11 11 روما','<p style=\"text-align:right;\">عطر أنثوي عصري يمزج بين الكشمش الأسود والفلفل الوردي مع قلب زهري من الياسمين. وتمنحه قاعدة الفانيليا وخشب الجياك لمسة دافئة وأنيقة تدوم.<br><strong>عائلة العطر:</strong> زهري شرقي<br><strong>نوع العطر:</strong> عصري وأنثوي<br><strong>المكونات الأساسية:</strong> الياسمين، الفانيليا، الكشمش الأسود، الفلفل الوردي، خشب الجياك<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p><hr><p>&nbsp;</p>',NULL),('ar',106,'11 11 سـكـانـدل','<p class=\"\" style=\"text-align:right;\" data-start=\"619\" data-end=\"988\">عطر جريء وحسي يفتتح بالعسل الحلو والبرتقال الأحمر العصير، يليه قلب زهري من الياسمين والغاردينيا، وتستقر القاعدة على الباتشولي والكراميل لتوقيع أنثوي لا يُنسى.<br><strong data-start=\"802\" data-end=\"818\">عائلة العطر:</strong> شرقي زهري<br><strong data-start=\"831\" data-end=\"845\">نوع العطر:</strong> حلو وجريء<br><strong data-start=\"858\" data-end=\"880\">المكونات الأساسية:</strong> العسل، البرتقال الأحمر، الياسمين، الغاردينيا، الباتشولي، الكراميل<br><strong data-start=\"949\" data-end=\"959\">النوع:</strong> عطر (EDP)<br><strong data-start=\"972\" data-end=\"982\">الحجم:</strong> 50 مل</p>',NULL),('ar',107,'11 11 سي','<p class=\"\" style=\"text-align:right;\" data-start=\"568\" data-end=\"917\">عطر أنثوي راقٍ يمزج بين رحيق الكشمش الأسود وقلب زهري من الورد والفريزيا، وتستقر القاعدة على الفانيليا والباتشولي لتوقيع أنيق يعكس القوة والنعومة.<br><strong data-start=\"738\" data-end=\"754\">عائلة العطر:</strong> شيبر زهري<br><strong data-start=\"767\" data-end=\"781\">نوع العطر:</strong> دافئ وأنيق<br><strong data-start=\"795\" data-end=\"817\">المكونات الأساسية:</strong> رحيق الكشمش الأسود، الورد، الفريزيا، الفانيليا، الباتشولي<br><strong data-start=\"878\" data-end=\"888\">النوع:</strong> عطر (EDP)<br><strong data-start=\"901\" data-end=\"911\">الحجم:</strong> 50 مل</p>',NULL),('ar',108,'11 11 سيلك كوين','<p class=\"\" style=\"text-align:right;\" data-start=\"586\" data-end=\"953\">عطر فاخر ومضيء يمزج بين الزعفران والباشن فروت مع قلب زهري من التوبروز والورد، وتستقر القاعدة على العود والفانيليا والأمبروكسان لتوقيع ناعم وحريري يدوم.<br><strong data-start=\"762\" data-end=\"778\">عائلة العطر:</strong> زهري شرقي<br><strong data-start=\"791\" data-end=\"805\">نوع العطر:</strong> ناعم وفاخر<br><strong data-start=\"819\" data-end=\"841\">المكونات الأساسية:</strong> الزعفران، الباشن فروت، التوبروز، الورد، العود، الفانيليا، الأمبروكسان<br><strong data-start=\"914\" data-end=\"924\">النوع:</strong> عطر (EDP)<br><strong data-start=\"937\" data-end=\"947\">الحجم:</strong> 50 مل</p>',NULL),('ar',109,'11 11 فالايا','<p class=\"\" style=\"text-align:right;\" data-start=\"600\" data-end=\"967\">عطر منعش ومضيء يبدأ بالبرغموت والدراق الأبيض، يليه قلب زهري من زهر البرتقال ونجيل الهند، وتستقر القاعدة على المسك والأمبروكسان لتوقيع أنثوي ناعم ومشرق.<br><strong data-start=\"776\" data-end=\"792\">عائلة العطر:</strong> زهري مسكي<br><strong data-start=\"805\" data-end=\"819\">نوع العطر:</strong> منعش وأنيق<br><strong data-start=\"833\" data-end=\"855\">المكونات الأساسية:</strong> البرغموت، الدراق الأبيض، زهر البرتقال، نجيل الهند، المسك، الأمبروكسان<br><strong data-start=\"928\" data-end=\"938\">النوع:</strong> عطر (EDP)<br><strong data-start=\"951\" data-end=\"961\">الحجم:</strong> 50 مل</p>',NULL),('ar',110,'11 11 فانيلا','<p class=\"\" style=\"text-align:right;\" data-start=\"559\" data-end=\"917\">عطر دافئ ولا يُقاوم يمزج بين الفانيليا الكريمية والتونكا مع لمسات من السكر البني والعنبر، ليمنحك توقيعاً عطرياً حلواً ومريحاً يدوم على البشرة بسحر أنثوي ناعم.<br><strong data-start=\"742\" data-end=\"758\">عائلة العطر:</strong> غورماند شرقي<br><strong data-start=\"774\" data-end=\"788\">نوع العطر:</strong> حلو ودافئ<br><strong data-start=\"801\" data-end=\"823\">المكونات الأساسية:</strong> الفانيليا، حبوب التونكا، السكر البني، العنبر، المسك<br><strong data-start=\"878\" data-end=\"888\">النوع:</strong> عطر (EDP)<br><strong data-start=\"901\" data-end=\"911\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"924\" data-end=\"1017\">&nbsp;</p>',NULL),('ar',111,'11 11 أليـكـسا','<p style=\"text-align:right;\">عطر فاخر وقوي يفتتح بالخزامى والقرفة الزاهية، يليه قلب من الورد البلغاري وخشب الأرز، وتستقر القاعدة على العود، والعنبر، والمسك لتوقيع عطري ملكي يدوم طويلاً.<br><strong>عائلة العطر:</strong> شرقي خشبي<br><strong>نوع العطر:</strong> غني وراقي<br><strong>المكونات الأساسية:</strong> الخزامى، القرفة، الورد، خشب الأرز، العود، العنبر، المسك<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',112,'11 11 إمبريال','<p style=\"text-align:right;\">عطر راقٍ وفاخر يبدأ بالتفاح الزاهي والزعفران، يليه قلب ناعم من الورد والجلد السويدي، وتستقر القاعدة على العنبر، الفانيليا، وخشب الصندل لتوقيع عطري أنيق يدوم طويلاً.<br><strong>عائلة العطر:</strong> شرقي زهري<br><strong>نوع العطر:</strong> دافئ وراقي<br><strong>المكونات الأساسية:</strong> التفاح، الزعفران، الورد، الجلد السويدي، العنبر، الفانيليا، خشب الصندل<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',113,'11 11 إنترلود بلاك','<p style=\"text-align:right;\">عطر غامض وجريء يبدأ بالبرغموت الحار وإكليل الجبل، يليه قلب غني من السوسن، اللبان، والمر، وتستقر القاعدة على الجلد، العود، والعنبر لتوقيع عطري عميق ومميز.<br><strong>عائلة العطر:</strong> شرقي خشبي<br><strong>نوع العطر:</strong> دخاني وراقي<br><strong>المكونات الأساسية:</strong> البرغموت، إكليل الجبل، السوسن، اللبان، المر، الجلد، العود، العنبر<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',114,'11 11 مالون','<p style=\"text-align:right;\">عطر منعش وحيوي يبدأ بالليم والماندرين العصير، متوازن مع الريحان العطري ولمسة من خشب العنبر لتوقيع أنيق ونظيف يدوم طويلاً.<br><strong>عائلة العطر:</strong> حمضي عطري<br><strong>نوع العطر:</strong> منعش ونظيف<br><strong>المكونات الأساسية:</strong> الليم، الماندرين، الريحان، خشب العنبر<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p><hr><p>&nbsp;</p>',NULL),('ar',115,'11 11 ماراكوجا','<p style=\"text-align:right;\">عطر استثنائي وجريء يجمع بين فاكهة الماراكويا الغنية والعود العميق مع لمسة من الزعفران الحار. ويُضفى الجلد وخشب الأكيغالاوود عمقاً وقوة لعطر لا يُنسى.<br><strong>عائلة العطر:</strong> فاكهي خشبي<br><strong>نوع العطر:</strong> جريء واستوائي<br><strong>المكونات الأساسية:</strong> فاكهة الماراكويا، الزعفران، العود، الجلد، خشب الأكيغالاوود<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',116,'11 11 ميغا','<p class=\"\" style=\"text-align:right;\" data-start=\"556\" data-end=\"900\">عطر مائي كثيف يجسد عمق المحيط اللامتناهي. يمزج بين النفحات البحرية والعنبر الرمادي والأعشاب البحرية والمسك، ليخلق توقيعاً عطرياً مالحاً وغامضاً يدوم طويلاً.<br><strong data-start=\"737\" data-end=\"753\">عائلة العطر:</strong> مائي خشبي<br><strong data-start=\"766\" data-end=\"780\">نوع العطر:</strong> بحري وكثيف<br><strong data-start=\"794\" data-end=\"816\">المكونات الأساسية:</strong> نوتات بحرية، عنبر رمادي، أعشاب بحرية، مسك<br><strong data-start=\"861\" data-end=\"871\">النوع:</strong> عطر (EDP)<br><strong data-start=\"884\" data-end=\"894\">الحجم:</strong> 50 مل</p><hr><p class=\"\" style=\"text-align:right;\" data-start=\"907\" data-end=\"976\">&nbsp;</p>',NULL),('ar',117,'11 11 عود وود','<p style=\"text-align:right;\">عطر ناعم وراقي يمزج بين العود النادر وخشب الصندل الكريمي مع لمسة من الهيل الحار. وتضفي القاعدة الدافئة من العنبر وحبوب التونكا طابعاً فاخراً وخالداً على العطر.<br><strong>عائلة العطر:</strong> شرقي خشبي<br><strong>نوع العطر:</strong> دافئ وراقي<br><strong>المكونات الأساسية:</strong> العود، خشب الصندل، الهيل، العنبر، التونكا<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',118,'11 11 بورا','<p class=\"\" style=\"text-align:right;\" data-start=\"599\" data-end=\"976\">عطر مشرق وعصري يفتتح بانفجار من الحمضيات والفواكه المتوسطية الحلوة. قلب العطر مليء بالمرح والفاكهة، وتضفي القاعدة من المسك الأبيض والعنبر والفانيليا نعومة وثباتًا طويلًا.<br><strong data-start=\"794\" data-end=\"810\">عائلة العطر:</strong> فاكهي شرقي<br><strong data-start=\"824\" data-end=\"838\">نوع العطر:</strong> منعش وحلو<br><strong data-start=\"851\" data-end=\"873\">المكونات الأساسية:</strong> الحمضيات، الفواكه المتوسطية، الفانيليا، المسك الأبيض، العنبر<br><strong data-start=\"937\" data-end=\"947\">النوع:</strong> عطر (EDP)<br><strong data-start=\"960\" data-end=\"970\">الحجم:</strong> 50 مل</p>',NULL),('ar',119,'11 11 سانتال','<p class=\"\" style=\"text-align:right;\" data-start=\"542\" data-end=\"841\">عطر ناعم ومميز يمزج بين خشب الصندل الكريمي والهيل والبنفسج مع لمسة جلدية مدخنة. عطر جريء ومريح في آنٍ واحد.<br><strong data-start=\"674\" data-end=\"690\">عائلة العطر:</strong> خشبي عطري<br><strong data-start=\"703\" data-end=\"717\">نوع العطر:</strong> كريمي ومدخن<br><strong data-start=\"732\" data-end=\"754\">المكونات الأساسية:</strong> خشب الصندل، الهيل، البنفسج، الجلد، خشب الأرز<br><strong data-start=\"802\" data-end=\"812\">النوع:</strong> عطر (EDP)<br><strong data-start=\"825\" data-end=\"835\">الحجم:</strong> 50 مل</p>',NULL),('ar',120,'11 11 ستيلار','<p class=\"\" style=\"text-align:right;\" data-start=\"557\" data-end=\"864\">عطر فاخر ومضيء يمزج بين زهر البرتقال والعنبر الكريمي مع لمسات من المسك الأبيض والزهور الناعمة. توقيع عطري سماوي وآسر.<br><strong data-start=\"699\" data-end=\"715\">عائلة العطر:</strong> شرقي زهري<br><strong data-start=\"728\" data-end=\"742\">نوع العطر:</strong> دافئ ومشرق<br><strong data-start=\"756\" data-end=\"778\">المكونات الأساسية:</strong> زهر البرتقال، العنبر، المسك، الزهور البيضاء<br><strong data-start=\"825\" data-end=\"835\">النوع:</strong> عطر (EDP)<br><strong data-start=\"848\" data-end=\"858\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"871\" data-end=\"936\">&nbsp;</p>',NULL),('ar',121,'11 11 تيروني','<p class=\"\" style=\"text-align:right;\" data-start=\"551\" data-end=\"880\">عطر عميق وناري يجسد جوهر الأرض والنار. يمزج بين العود الغني والأخشاب المدخنة والراتنجات مع لمسة من التوت الأحمر لتوقيع عطري قوي وأصيل.<br><strong data-start=\"710\" data-end=\"726\">عائلة العطر:</strong> شرقي خشبي<br><strong data-start=\"739\" data-end=\"753\">نوع العطر:</strong> ترابي ومدخن<br><strong data-start=\"768\" data-end=\"790\">المكونات الأساسية:</strong> العود، الراتنجات، الأخشاب، البخور، التوت الأحمر<br><strong data-start=\"841\" data-end=\"851\">النوع:</strong> عطر (EDP)<br><strong data-start=\"864\" data-end=\"874\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"887\" data-end=\"958\">&nbsp;</p>',NULL),('ar',122,'11 11 ميمو','<p class=\"\" style=\"text-align:right;\" data-start=\"572\" data-end=\"955\">عطر بري وكاريزمي يمزج بين التوابل الدافئة والجلد والنباتات العطرية. يلتقي الهيل والزعفران مع قلب من إبرة الراعي والكمون، وتستقر القاعدة على الجلد ونجيل الهند لتوقيع عطري آسر وفاخر.<br><strong data-start=\"777\" data-end=\"793\">عائلة العطر:</strong> جلدي تابلي<br><strong data-start=\"807\" data-end=\"821\">نوع العطر:</strong> دافئ وجريء<br><strong data-start=\"835\" data-end=\"857\">المكونات الأساسية:</strong> الهيل، الزعفران، إبرة الراعي، الكمون، الجلد، نجيل الهند<br><strong data-start=\"916\" data-end=\"926\">النوع:</strong> عطر (EDP)<br><strong data-start=\"939\" data-end=\"949\">الحجم:</strong> 50 مل</p>',NULL),('ar',123,'11 11 عود','<p class=\"\" style=\"text-align:right;\" data-start=\"561\" data-end=\"904\">عطر فاخر وقوي يمزج بين العود الغني والزعفران وجوزة الطيب مع لمسة من اللافندر. وتمنح القاعدة من الباتشولي والمسك عمقاً وأناقة لعطر مميز وفخم.<br><strong data-start=\"726\" data-end=\"742\">عائلة العطر:</strong> شرقي تابلي<br><strong data-start=\"756\" data-end=\"770\">نوع العطر:</strong> جريء وملكي<br><strong data-start=\"784\" data-end=\"806\">المكونات الأساسية:</strong> العود، الزعفران، جوزة الطيب، اللافندر، الباتشولي، المسك<br><strong data-start=\"865\" data-end=\"875\">النوع:</strong> عطر (EDP)<br><strong data-start=\"888\" data-end=\"898\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"911\" data-end=\"1007\">&nbsp;</p>',NULL),('ar',124,'11 11 أوراچ','<p class=\"\" style=\"text-align:right;\" data-start=\"541\" data-end=\"878\">عطر أنيق وعميق يمزج بين نجيل الهند والباتشولي مع لمسات منعشة من السوسن ونفحات الفلفل. وتمنحه القاعدة الخشبية والمسكية توقيعاً نقياً وواثقاً يدوم.<br><strong data-start=\"711\" data-end=\"727\">عائلة العطر:</strong> خشبي ترابي<br><strong data-start=\"741\" data-end=\"755\">نوع العطر:</strong> منعش وعميق<br><strong data-start=\"769\" data-end=\"791\">المكونات الأساسية:</strong> نجيل الهند، الباتشولي، السوسن، الفلفل، المسك<br><strong data-start=\"839\" data-end=\"849\">النوع:</strong> عطر (EDP)<br><strong data-start=\"862\" data-end=\"872\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"885\" data-end=\"967\">&nbsp;</p>',NULL),('ar',125,'11 11 ميل','<p class=\"\" style=\"text-align:right;\" data-start=\"583\" data-end=\"937\">عطر جريء وخالد يبدأ بالنعناع المنعش واللافندر، يتوسطه القرفة وزهر البرتقال، وتستقر القاعدة على الفانيليا والتونكا لتوقيع عطري ذكوري مغرٍ ولا يُنسى.<br><strong data-start=\"755\" data-end=\"771\">عائلة العطر:</strong> شرقي فوجير<br><strong data-start=\"785\" data-end=\"799\">نوع العطر:</strong> منعش ودافئ<br><strong data-start=\"813\" data-end=\"835\">المكونات الأساسية:</strong> النعناع، اللافندر، القرفة، زهر البرتقال، الفانيليا، التونكا<br><strong data-start=\"898\" data-end=\"908\">النوع:</strong> عطر (EDP)<br><strong data-start=\"921\" data-end=\"931\">الحجم:</strong> 50 مل</p><hr><p class=\"\" data-start=\"944\" data-end=\"1016\">&nbsp;</p>',NULL),('ar',126,'test','',''),('ar',128,'11 11 Male','<p>A bold and timeless fragrance that opens with fresh mint and lavender, followed by warm cinnamon and orange blossom, and finishes with vanilla and tonka bean for a seductive, masculine signature.<br><strong>Fragrance Family:</strong> Oriental Fougere<br><strong>Scent Type:</strong> Fresh &amp; Warm<br><strong>Key Ingredients:</strong> Mint, Lavender, Cinnamon, Orange Blossom, Vanilla, Tonka Bean<br><strong>Type:</strong> Eau de Parfum (EDP)<br><strong>Size:</strong> 50ml</p>',NULL),('ar',129,'11 11 ميل','<p style=\"text-align:right;\">عطر جريء وخالد يبدأ بالنعناع المنعش واللافندر، يتوسطه القرفة وزهر البرتقال، وتستقر القاعدة على الفانيليا والتونكا لتوقيع عطري ذكوري مغرٍ ولا يُنسى.<br><strong>عائلة العطر:</strong> شرقي فوجير<br><strong>نوع العطر:</strong> منعش ودافئ<br><strong>المكونات الأساسية:</strong> النعناع، اللافندر، القرفة، زهر البرتقال، الفانيليا، التونكا<br><strong>النوع:</strong> عطر (EDP)<br><strong>الحجم:</strong> 50 مل</p>',NULL),('ar',130,'11 11 Orage','<p>A refined and earthy fragrance that combines vetiver and patchouli with crisp iris and peppery notes. Anchored by a musky, woody base, it delivers a clean and confident signature.<br><strong>Fragrance Family:</strong> Woody Earthy<br><strong>Scent Type:</strong> Fresh & Grounded<br><strong>Key Ingredients:</strong> Vetiver, Patchouli, Iris, Pepper, Musk<br><strong>Type:</strong> Eau de Parfum (EDP)<br><strong>Size:</strong> 50ml</p>',''),('ar',131,'11 11 نويت','<p style=\"text-align:right;\"><span>اتحاد آسر يجمع بين العنبر الحسي والورد الأنيق. يوازن هذا العطر دفء العنبر الذهبي مع قلب من الورد التركي الغني، وتزيده نفحات من الفلفل الوردي والحمضيات تألقًا لإضفاء جاذبية آسرة تغمر الحواس.</span>&nbsp;<br>&nbsp;</p><p style=\"text-align:right;\"><span><strong>عائلة العطر:</strong> دافئ وتابلي</span></p><p style=\"text-align:right;\"><span><strong>نوع العطر:</strong> زهري عنبري</span></p><p style=\"text-align:right;\"><span><strong>المكونات الأساسية:</strong> العنبر، الورد الدمشقي، الفلفل الوردي، الباتشولي</span></p><p style=\"text-align:right;\"><span><strong>النوع:</strong> عطر (EDP)</span></p><p style=\"text-align:right;\"><span><strong>الحجم:</strong> 50 مل</span></p>',NULL),('ar',132,'11 11 ريفييرا','<p style=\"text-align:right;\" data-pm-slice=\"1 1 []\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">عطر مشرق وأنيق يوازن بين الأزهار الغنية والحلاوة الخضراء المنعشة. تتشابك نفحات الورد المخملي مع التين اليانع والأوراق الخضراء، لتخلق عبيرًا مشمسًا وأنيقًا يستحضر حديقة متوسطية في أوج تفتحها.</span><br>&nbsp;</p><p style=\"text-align:right;\"><span data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">عائلة العطر:</strong> زهري</span></p><p style=\"text-align:right;\"><span data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">نوع العطر:</strong> زهري أخضر</span></p><p style=\"text-align:right;\"><span data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">المكونات الأساسية:</strong> التين، الورد، أوراق التين، المسك</span></p><p style=\"text-align:right;\"><span data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">النوع:</strong> عطر (EDP)</span></p><p style=\"text-align:right;\"><span data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">الحجم:</strong> 50 مل</span></p>',NULL),('ar',133,'11 11 سيربنت فويس','<p style=\"text-align:right;\" data-pm-slice=\"1 1 []\" data-mce-fragment=\"1\"><span style=\"font-size:15px;\"><span data-mce-fragment=\"1\">عطر قوي وآسر مبني حول عود داكن ودخاني. تعزز نفحات الزعفران الغريبة والباتشولي الترابي من غناه، لتبدع عبيرًا ساحرًا ذا جاذبية أخاذة بحق.</span></span><br>&nbsp;</p><p style=\"text-align:right;\"><span style=\"font-size:13px;\"><span style=\"font-size:1.4em;\" data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">عائلة العطر:</strong> دافئ وتابلي</span></span><br><span style=\"font-size:13px;\"><span style=\"font-size:1.4em;\" data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">نوع العطر:</strong> عود و باتشولي</span></span><br><span style=\"font-size:13px;\"><span style=\"font-size:1.4em;\" data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">المكونات الأساسية:</strong> العود، الزعفران، الباتشولي، البخور</span></span><br><span style=\"font-size:13px;\"><span style=\"font-size:1.4em;\" data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">النوع:</strong> عطر (EDP)</span></span><br><span style=\"font-size:13px;\"><span style=\"font-size:1.4em;\" data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">الحجم:</strong> 50 مل</span></span></p>',NULL),('ar',134,'Toyota Fortunar','<p>Toyota Fortunar</p><p>Toyota Fortunar</p><p>Toyota Fortunar</p>','<p>Toyota Fortunar</p><p>Toyota Fortunar</p><p>Toyota Fortunar</p>');
