INSERT INTO `pages` VALUES (1,'Homepage','<p><img src=\"https://ae.1111perfume.com/storage/mg5-banner-english-1.jpg\" alt=\"MG5-BANNER-ENGLISH-1\" loading=\"lazy\"></p><shortcode>[simple-slider key=\"home-slider\"][/simple-slider]</shortcode><p><img src=\"https://ae.1111perfume.com/storage/womens-english.jpg\" alt=\"WOMENS-ENGLISH\" loading=\"lazy\"></p><shortcode>[product-category-products category_id=\"32\" limit=\"8\"][/product-category-products]</shortcode><p><img src=\"https://ae.1111perfume.com/storage/terroni-mens-perfume-english.jpg\" alt=\"TERRONI-MENS-PERFUME-ENGLISH\" loading=\"lazy\"></p><shortcode>[product-category-products category_id=\"31\" limit=\"8\"][/product-category-products]</shortcode><p><img src=\"https://ae.1111perfume.com/storage/unisex-banner-english.jpg\" alt=\"UNISEX-BANNER-ENGLISH\" loading=\"lazy\"></p><shortcode>[product-category-products category_id=\"33\" limit=\"8\"][/product-category-products]</shortcode>',1,NULL,'homepage','','published','2025-02-25 09:16:13','2025-05-02 23:10:14'),(6,'Contact','<shortcode>[contact-form display_fields=\"phone,email,subject,address\" mandatory_fields=\"phone,email\"][/contact-form]</shortcode>',1,NULL,'default','','published','2025-02-25 09:16:13','2025-04-24 10:22:39'),(7,'About Us','<p>&nbsp;</p><h3><strong>About Us</strong></h3><p><strong>11:11 Perfume</strong> is a luxury fragrance house operated under<br><a href=\"https://feranchesco.com/\" rel=\"noopener\" title=\"Feranchesco.com\" target=\"_blank\"><strong>Feranchesco Professional</strong></a><strong> </strong>(<i>A Leading Cosmetics Brand Globally</i>).<br><br>Its created with a passion for crafting exceptional perfumes that captivate the senses and embody elegance, sophistication, and timeless allure. As a rising name in the world of fine fragrances, we are proud to introduce our exquisite collection to the <strong>GCC Region and IRAQ, </strong>where the art of perfumery is deeply cherished and celebrated.</p><p>At <strong>11:11 Perfume</strong>, we specialize in developing high-quality fragrances that tell stories through scent. Our commitment to excellence is reflected in every bottle, as we meticulously select the finest ingredients from around the world. By blending <strong>traditional artistry</strong> with <strong>innovative techniques</strong>, we create unique, unforgettable perfumes that leave a lasting impression. Each scent is designed to evoke emotion, inspire confidence, and enhance individuality.</p><p>More than just fragrances, our perfumes are an <strong>expression of identity, culture, and luxury</strong>. With a deep understanding of the refined tastes of our<strong>&nbsp;</strong>customers, we strive to deliver unmatched quality and a personalized experience that resonates with the region’s rich heritage of fragrance appreciation.</p><p>Whether you seek a <strong>bold, powerful statement</strong> or a <strong>soft, delicate essence</strong>, our collections cater to every personality and occasion. At <strong>11:11 Perfume</strong>, we are dedicated to bringing you an olfactory experience that is as unique as you are.</p><p>Join us on this exciting journey as we redefine <strong>luxury fragrance</strong> in the <meta charset=\"utf-8\"><strong>GCC Region and IRAQ, </strong>where excellence is the standard and every scent is crafted to perfection.</p>',1,NULL,'default','','published','2025-02-25 09:16:13','2025-05-01 12:40:56'),(8,'Cookie Policy','<h3 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 1.8rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\"><strong style=\"box-sizing:inherit;\">About Us</strong></h3><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:inherit;\">11:11 Perfume</strong> is a luxury fragrance house operated under the<br><a style=\"box-sizing:inherit;color:rgba(var(--color-link),var(--alpha-link));text-decoration-thickness:0.1rem;text-underline-offset:0.3rem;transition:text-decoration-thickness var(--duration-short) ease;\" href=\"https://feranchesco.com/\" title=\"Feranchesco.com\" rel=\"noopener\" target=\"_blank\"><strong style=\"box-sizing:inherit;\">Feranchesco</strong></a><strong style=\"box-sizing:inherit;\"> legal entity (License No. 1351054).</strong><br><br>Its created with a passion for crafting exceptional perfumes that captivate the senses and embody elegance, sophistication, and timeless allure. As a rising name in the world of fine fragrances, we are proud to introduce our exquisite collection to the <strong style=\"box-sizing:inherit;\">GCC region</strong>—where the art of perfumery is deeply cherished and celebrated.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">At <strong style=\"box-sizing:inherit;\">11:11 Perfume</strong>, we specialize in developing high-quality fragrances that tell stories through scent. Our commitment to excellence is reflected in every bottle, as we meticulously select the finest ingredients from around the world. By blending <strong style=\"box-sizing:inherit;\">traditional artistry</strong> with <strong style=\"box-sizing:inherit;\">innovative techniques</strong>, we create unique, unforgettable perfumes that leave a lasting impression. Each scent is designed to evoke emotion, inspire confidence, and enhance individuality.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">More than just fragrances, our perfumes are an <strong style=\"box-sizing:inherit;\">expression of identity, culture, and luxury</strong>. With a deep understanding of the refined tastes of our <strong style=\"box-sizing:inherit;\">GCC customers</strong>, we strive to deliver unmatched quality and a personalized experience that resonates with the region’s rich heritage of fragrance appreciation.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Whether you seek a <strong style=\"box-sizing:inherit;\">bold, powerful statement</strong> or a <strong style=\"box-sizing:inherit;\">soft, delicate essence</strong>, our collections cater to every personality and occasion. At <strong style=\"box-sizing:inherit;\">11:11 Perfume</strong>, we are dedicated to bringing you an olfactory experience that is as unique as you are.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;margin-bottom:0px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Join us on this exciting journey as we redefine <strong style=\"box-sizing:inherit;\">luxury fragrance</strong> in the <strong style=\"box-sizing:inherit;\">GCC region</strong>—where excellence is the standard and every scent is crafted to perfection.</p>',1,NULL,'default','','published','2025-02-25 09:16:13','2025-04-22 10:24:55'),(10,'Returns &amp; Exchanges','<h1 class=\"main-page-title page-title h0 scroll-trigger animate--fade-in\" style=\"-webkit-text-stroke-width:0px;animation:var(--animation-fade-in);background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 5.2rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));margin-bottom:4rem;margin-top:0px;opacity:1;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Return Policy</h1><div class=\"rte scroll-trigger animate--slide-in\" style=\"-webkit-text-stroke-width:0px;animation-delay:calc(var(--animation-order) * 75ms);animation-direction:;animation-duration:;animation-fill-mode:;animation-iteration-count:;animation-name:;animation-play-state:;animation-range-end:;animation-range-start:;animation-timeline:;animation-timing-function:;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;opacity:0.01;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;transform:translateY(2rem);white-space:normal;widows:2;word-spacing:0px;\"><p style=\"box-sizing:inherit;margin-top:0px;\">At <strong style=\"box-sizing:inherit;\">11:11</strong>, your satisfaction is our top priority. To make your shopping experience worry-free, we’ve outlined the following return policy:</p><p style=\"box-sizing:inherit;\"><strong style=\"box-sizing:inherit;\">Tester for Your Convenience</strong><br>Every product comes with a tester. Please use the tester first to ensure the fragrance meets your expectations.</p><p style=\"box-sizing:inherit;\"><strong style=\"box-sizing:inherit;\">Return Conditions</strong></p><ul style=\"box-sizing:inherit;list-style-position:inside;padding-left:2rem;\"><li style=\"box-sizing:inherit;list-style:inherit;\">Returns must be requested within <strong style=\"box-sizing:inherit;\">3 days</strong> of receiving the product.</li><li style=\"box-sizing:inherit;list-style:inherit;margin-bottom:0px;\">The product must remain in its <strong style=\"box-sizing:inherit;\">original condition</strong>, and the <strong style=\"box-sizing:inherit;\">outer cover must not be opened</strong>.</li></ul><p style=\"box-sizing:inherit;\"><strong style=\"box-sizing:inherit;\">How to Return</strong></p><ul style=\"box-sizing:inherit;list-style-position:inside;padding-left:2rem;\"><li style=\"box-sizing:inherit;list-style:inherit;\">Contact our customer service team within the 3-day period to initiate the return.</li><li style=\"box-sizing:inherit;list-style:inherit;margin-bottom:0px;\">Ensure both the unopened product and the tester are packed securely for return shipping.</li></ul><p style=\"box-sizing:inherit;\"><strong style=\"box-sizing:inherit;\">Refund Process</strong></p><ul style=\"box-sizing:inherit;list-style-position:inside;padding-left:2rem;\"><li style=\"box-sizing:inherit;list-style:inherit;\">Once we receive and inspect the returned items, your refund will be processed.</li><li style=\"box-sizing:inherit;list-style:inherit;margin-bottom:0px;\">Refunds will be issued within <strong style=\"box-sizing:inherit;\">7 business days</strong> to your original payment method.</li></ul><p style=\"box-sizing:inherit;\"><strong style=\"box-sizing:inherit;\">Important Notes</strong></p><ul style=\"box-sizing:inherit;list-style-position:inside;padding-left:2rem;\"><li style=\"box-sizing:inherit;list-style:inherit;\">Both the product and the tester must be returned together in their original condition to qualify for a refund.</li><li style=\"box-sizing:inherit;list-style:inherit;margin-bottom:0px;\">Any signs of tampering or use will result in the return being declined.</li></ul><p style=\"box-sizing:inherit;margin-bottom:0px;\">For further assistance, feel free to reach out to our support team.</p></div>',1,NULL,'default','','published','2025-02-25 09:16:13','2025-04-22 10:27:17'),(12,'Privacy Policy','<div class=\"shopify-policy__title\" style=\"box-sizing:inherit;text-align:center;\"><h1 style=\"box-sizing:inherit;color:rgb(var(--color-foreground));font-family:var(--font-heading-family);font-size:calc(var(--font-heading-scale) * 4rem);font-style:var(--font-heading-style);font-weight:var(--font-heading-weight);letter-spacing:calc(var(--font-heading-scale) * .06rem);line-height:calc(1 + .3/max(1,var(--font-heading-scale)));word-break:break-word;\">Privacy policy</h1></div><div class=\"shopify-policy__body\" style=\"box-sizing:inherit;\"><div class=\"rte\" style=\"box-sizing:inherit;\"><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;margin-top:0px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Last updated: January 20, 2025</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">This Privacy Policy describes how 11:11 Perfume (the \"Site\", \"we\", \"us\", or \"our\") collects, uses, and discloses your personal information when you visit, use our services, or make a purchase from 1111perfume.com&nbsp; or otherwise communicate with us regarding the Site . For purposes of this Privacy Policy, \"you\" and \"your\" means you as the user of the Services, whether you are a customer, website visitor, or another individual whose information we have collected pursuant to this Privacy Policy.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Please read this Privacy Policy carefully. By using and accessing any of the Services, you agree to the collection, use, and disclosure of your information as described in this Privacy Policy. If you do not agree to this Privacy Policy, please do not use or access any of the Services.</p><h2 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 2.4rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Changes to This Privacy Policy</h2><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">We may update this Privacy Policy from time to time, including to reflect changes to our practices or for other operational, legal, or regulatory reasons. We will post the revised Privacy Policy on the Site, update the \"Last updated\" date and take any other steps required by applicable law.</p><h2 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 2.4rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">How We Collect and Use Your Personal Information</h2><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">To provide the Services, we collect personal information about you from a variety of sources, as set out below. The information that we collect and use varies depending on how you interact with us.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">In addition to the specific uses set out below, we may use information we collect about you to communicate with you, provide or improve or improve the Services, comply with any applicable legal obligations, enforce any applicable terms of service, and to protect or defend the Services, our rights, and the rights of our users or others.</p><h3 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 1.8rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">What Personal Information We Collect</h3><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">The types of personal information we obtain about you depends on how you interact with our Site and use our Services. When we use the term \"personal information\", we are referring to information that identifies, relates to, describes or can be associated with you. The following sections describe the categories and specific types of personal information we collect.</p><h3 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 1.8rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Information We Collect Directly from You</h3><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Information that you directly submit to us through our Services may include:</p><ul style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;list-style-position:inside;orphans:2;padding-left:2rem;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Contact details</strong> including your name, address, phone number, and email.</li><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Order information</strong> including your name, billing address, shipping address, payment confirmation, email address, and phone number.</li><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Account information</strong> including your username, password, security questions and other information used for account security purposes.</li><li style=\"box-sizing:inherit;list-style:inherit;margin-bottom:0px;\"><strong style=\"box-sizing:inherit;\">Customer support information</strong> including the information you choose to include in communications with us, for example, when sending a message through the Services.</li></ul><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Some features of the Services may require you to directly provide us with certain information about yourself. You may elect not to provide this information, but doing so may prevent you from using or accessing these features.</p><h3 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 1.8rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Information We Collect about Your Usage</h3><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">We may also automatically collect certain information about your interaction with the Services (\"<strong style=\"box-sizing:inherit;\">Usage Data</strong>\"). To do this, we may use cookies, pixels and similar technologies (\"<strong style=\"box-sizing:inherit;\">Cookies</strong>\"). Usage Data may include information about how you access and use our Site and your account, including device information, browser information, information about your network connection, your IP address and other information regarding your interaction with the Services.</p><h3 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 1.8rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Information We Obtain from Third Parties</h3><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Finally, we may obtain information about you from third parties, including from vendors and service providers who may collect information on our behalf, such as:</p><ul style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;list-style-position:inside;orphans:2;padding-left:2rem;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><li style=\"box-sizing:inherit;list-style:inherit;\">Companies who support our Site and Services, such as Shopify.</li><li style=\"box-sizing:inherit;list-style:inherit;\">Our payment processors, who collect payment information (e.g., bank account, credit or debit card information, billing address) to process your payment in order to fulfill your orders and provide you with products or services you have requested, in order to perform our contract with you.</li><li style=\"box-sizing:inherit;list-style:inherit;margin-bottom:0px;\">When you visit our Site, open or click on emails we send you, or interact with our Services or advertisements, we, or third parties we work with, may automatically collect certain information using online tracking technologies such as pixels, web beacons, software developer kits, third-party libraries, and cookies.</li></ul><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Any information we obtain from third parties will be treated in accordance with this Privacy Policy. Also see the section below, <i style=\"box-sizing:inherit;\">Third Party Websites and Links.</i></p><h3 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 1.8rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">How We Use Your Personal Information</h3><ul style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;list-style-position:inside;orphans:2;padding-left:2rem;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Providing Products and Services.</strong> We use your personal information to provide you with the Services in order to perform our contract with you, including to process your payments, fulfill your orders, to send notifications to you related to your account, purchases, returns, exchanges or other transactions, to create, maintain and otherwise manage your account, to arrange for shipping, facilitate any returns and exchanges and other features and functionalities related to your account. We may also enhance your shopping experience by enabling Shopify to match your account with other Shopify services that you may choose to use. In this case, Shopify will process your information as set forth in its Privacy Policy and Consumer Privacy Policy.</li><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Marketing and Advertising.</strong> We may use your personal information for marketing and promotional purposes, such as to send marketing, advertising and promotional communications by email, text message or postal mail, and to show you advertisements for products or services. This may include using your personal information to better tailor the Services and advertising on our Site and other websites.</li><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Security and Fraud Prevention.</strong> We use your personal information to detect, investigate or take action regarding possible fraudulent, illegal or malicious activity. If you choose to use the Services and register an account, you are responsible for keeping your account credentials safe. We highly recommend that you do not share your username, password, or other access details with anyone else. If you believe your account has been compromised, please contact us immediately..</li><li style=\"box-sizing:inherit;list-style:inherit;margin-bottom:0px;\"><strong style=\"box-sizing:inherit;\">Communicating with You and Service Improvement.</strong> We use your personal information to provide you with customer support and improve our Services. This is in our legitimate interests in order to be responsive to you, to provide effective services to you, and to maintain our business relationship with you</li></ul><h2 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 2.4rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Cookies</h2><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Like many websites, we use Cookies on our Site. For specific information about the Cookies that we use related to powering our store with Shopify, see <a style=\"box-sizing:inherit;color:rgba(var(--color-link),var(--alpha-link));text-decoration-thickness:0.1rem;text-underline-offset:0.3rem;transition:text-decoration-thickness var(--duration-short) ease;\" href=\"https://www.shopify.com/legal/cookies\" target=\"_blank\">https://www.shopify.com/legal/cookies</a>. We use Cookies to power and improve our Site and our Services (including to remember your actions and preferences), to run analytics and better understand user interaction with the Services (in our legitimate interests to administer, improve and optimize the Services). We may also permit third parties and services providers to use Cookies on our Site to better tailor the services, products and advertising on our Site and other websites.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Most browsers automatically accept Cookies by default, but you can choose to set your browser to remove or reject Cookies through your browser controls. Please keep in mind that removing or blocking Cookies can negatively impact your user experience and may cause some of the Services, including certain features and general functionality, to work incorrectly or no longer be available. Additionally, blocking Cookies may not completely prevent how we share information with third parties such as our advertising partners.</p><h2 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 2.4rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">How We Disclose Personal Information</h2><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">In certain circumstances, we may disclose your personal information to third parties for contract fulfillment purposes, legitimate purposes and other reasons subject to this Privacy Policy. Such circumstances may include:</p><ul style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;list-style-position:inside;orphans:2;padding-left:2rem;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><li style=\"box-sizing:inherit;list-style:inherit;\">With vendors or other third parties who perform services on our behalf (e.g., IT management, payment processing, data analytics, customer support, cloud storage, fulfillment and shipping).</li><li style=\"box-sizing:inherit;list-style:inherit;\">With business and marketing partners to provide services and advertise to you. Our business and marketing partners will use your information in accordance with their own privacy notices.</li><li style=\"box-sizing:inherit;list-style:inherit;\">When you direct, request us or otherwise consent to our disclosure of certain information to third parties, such as to ship you products or through your use of social media widgets or login integrations, with your consent.</li><li style=\"box-sizing:inherit;list-style:inherit;\">With our affiliates or otherwise within our corporate group, in our legitimate interests to run a successful business.</li><li style=\"box-sizing:inherit;list-style:inherit;margin-bottom:0px;\">In connection with a business transaction such as a merger or bankruptcy, to comply with any applicable legal obligations (including to respond to subpoenas, search warrants and similar requests), to enforce any applicable terms of service, and to protect or defend the Services, our rights, and the rights of our users or others.</li></ul><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">We disclose the following categories of personal information and sensitive personal information about users for the purposes set out above in <i style=\"box-sizing:inherit;\">\"How we Collect and Use your Personal Information\"</i> and <i style=\"box-sizing:inherit;\">\"How we Disclose Personal Information\"</i>:</p><figure class=\"table\"><table style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);border-collapse:collapse;border-style:hidden;box-shadow:0 0 0 .1rem rgba(var(--color-foreground),.2);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:1.4rem;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;table-layout:fixed;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><thead><tr style=\"box-sizing:inherit;\"><th style=\"border-color:rgba(var(--color-foreground),.2);border-width:.1rem;box-sizing:inherit;padding:1em;\">Category</th><th style=\"border-color:rgba(var(--color-foreground),.2);border-width:.1rem;box-sizing:inherit;padding:1em;\">Categories of Recipients</th></tr></thead><tbody style=\"box-sizing:inherit;\"><tr style=\"box-sizing:inherit;\"><td style=\"border-color:rgba(var(--color-foreground),.2);border-width:.1rem;box-sizing:inherit;padding:1em 1.2rem;\"><ul style=\"box-sizing:inherit;list-style-position:inside;padding-left:2rem;\"><li style=\"box-sizing:inherit;list-style:inherit;\">Identifiers such as basic contact details and certain order and account information</li><li style=\"box-sizing:inherit;list-style:inherit;\">Commercial information such as order information, shopping information and customer support information</li><li style=\"box-sizing:inherit;list-style:inherit;\">Internet or other similar network activity, such as Usage Data</li><li style=\"box-sizing:inherit;list-style:inherit;margin-bottom:0px;\">Geolocation data such as locations determined by an IP address or other technical measures</li></ul></td><td style=\"border-color:rgba(var(--color-foreground),.2);border-width:.1rem;box-sizing:inherit;padding:1em 1.2rem;\"><ul style=\"box-sizing:inherit;list-style-position:inside;padding-left:2rem;\"><li style=\"box-sizing:inherit;list-style:inherit;\">Vendors and third parties who perform services on our behalf (such as Internet service providers, payment processors, fulfillment partners, customer support partners and data analytics providers)</li><li style=\"box-sizing:inherit;list-style:inherit;\">Business and marketing partners</li><li style=\"box-sizing:inherit;list-style:inherit;margin-bottom:0px;\">Affiliates</li></ul></td></tr></tbody></table></figure><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">We do not use or disclose sensitive personal information without your consent or for the purposes of inferring characteristics about you.</p><h2 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 2.4rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Third Party Websites and Links</h2><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Our Site may provide links to websites or other online platforms operated by third parties. If you follow links to sites not affiliated or controlled by us, you should review their privacy and security policies and other terms and conditions. We do not guarantee and are not responsible for the privacy or security of such sites, including the accuracy, completeness, or reliability of information found on these sites. Information you provide on public or semi-public venues, including information you share on third-party social networking platforms may also be viewable by other users of the Services and/or users of those third-party platforms without limitation as to its use by us or by a third party. Our inclusion of such links does not, by itself, imply any endorsement of the content on such platforms or of their owners or operators, except as disclosed on the Services.</p><h2 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 2.4rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Children\'s Data</h2><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">The Services are not intended to be used by children, and we do not knowingly collect any personal information about children. If you are the parent or guardian of a child who has provided us with their personal information, you may contact us using the contact details set out below to request that it be deleted.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">As of the Effective Date of this Privacy Policy, we do not have actual knowledge that we “share” or “sell” (as those terms are defined in applicable law) personal information of individuals under 16 years of age.</p><h2 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 2.4rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Security and Retention of Your Information</h2><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Please be aware that no security measures are perfect or impenetrable, and we cannot guarantee “perfect security.” In addition, any information you send to us may not be secure while in transit. We recommend that you do not use insecure channels to communicate sensitive or confidential information to us.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">How long we retain your personal information depends on different factors, such as whether we need the information to maintain your account, to provide the Services, comply with legal obligations, resolve disputes or enforce other applicable contracts and policies.</p><h2 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 2.4rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Your Rights</h2><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Depending on where you live, you may have some or all of the rights listed below in relation to your personal information. However, these rights are not absolute, may apply only in certain circumstances and, in certain cases, we may decline your request as permitted by law.</p><ul style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;list-style-position:inside;orphans:2;padding-left:2rem;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Right to Access / Know</strong>: You may have a right to request access to personal information that we hold about you, including details relating to the ways in which we use and share your information.</li><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Right to Delete</strong>: You may have a right to request that we delete personal information we maintain about you.</li><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Right to Correct</strong>: You may have a right to request that we correct inaccurate personal information we maintain about you.</li><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Right of Portability</strong>: You may have a right to receive a copy of the personal information we hold about you and to request that we transfer it to a third party, in certain circumstances and with certain exceptions.</li><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Restriction of Processing</strong>: You may have the right to ask us to stop or restrict our processing of personal information.</li><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Withdrawal of Consent</strong>: Where we rely on consent to process your personal information, you may have the right to withdraw this consent.</li><li style=\"box-sizing:inherit;list-style:inherit;\"><strong style=\"box-sizing:inherit;\">Appeal</strong>: You may have a right to appeal our decision if we decline to process your request. You can do so by replying directly to our denial.</li><li style=\"box-sizing:inherit;list-style:inherit;margin-bottom:0px;\"><strong style=\"box-sizing:inherit;\">Managing Communication Preferences</strong>: We may send you promotional emails, and you may opt out of receiving these at any time by using the unsubscribe option displayed in our emails to you. If you opt out, we may still send you non-promotional emails, such as those about your account or orders that you have made.</li></ul><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">You may exercise any of these rights where indicated on our Site or by contacting us using the contact details provided below.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">We will not discriminate against you for exercising any of these rights. We may need to collect information from you to verify your identity, such as your email address or account information, before providing a substantive response to the request. In accordance with applicable laws, you may designate an authorized agent to make requests on your behalf to exercise your rights. Before accepting such a request from an agent, we will require that the agent provide proof you have authorized them to act on your behalf, and we may need you to verify your identity directly with us. We will respond to your request in a timely manner as required under applicable law.</p><h2 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 2.4rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Complaints</h2><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">If you have complaints about how we process your personal information, please contact us using the contact details provided below. If you are not satisfied with our response to your complaint, depending on where you live you may have the right to appeal our decision by contacting us using the contact details set out below, or lodge your complaint with your local data protection authority.</p><h2 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 2.4rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">International Users</h2><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Please note that we may transfer, store and process your personal information outside the country you live in. Your personal information is also processed by staff and third party service providers and partners in these countries.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">If we transfer your personal information out of Europe, we will rely on recognized transfer mechanisms like the European Commission\'s Standard Contractual Clauses, or any equivalent contracts issued by the relevant competent authority of the UK, as relevant, unless the data transfer is to a country that has been determined to provide an adequate level of protection.</p><h2 style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgb(var(--color-foreground));font-family:Assistant, sans-serif;font-size:calc(var(--font-heading-scale) * 2.4rem);font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:var(--font-heading-weight);letter-spacing:0.6px;line-height:calc(1 + .3/max(1,var(--font-heading-scale)));orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-break:break-word;word-spacing:0px;\">Contact</h2><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:inherit;color:rgba(18, 18, 18, 0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:0.6px;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><span style=\"box-sizing:inherit;\">Should you have any questions about our privacy practices or this Privacy Policy, or if you would like to exercise any of the rights available to you, please call or email us at care@1111perfume.com.</span></p></div></div><p><br>&nbsp;</p>',1,NULL,'default','','published','2025-02-25 09:16:13','2025-04-22 10:25:53'),(15,'Special Offers','<shortcode>[product-collections title=\"Featured Products\" limit=\"8\"][/product-collections]</shortcode>',2,NULL,'default','','published','2025-04-22 15:47:16','2025-04-22 15:47:55');
