INSERT INTO `pages_translations` VALUES ('ar',1,'الصفحة الرئيسية',NULL,'<p><img src=\"https://ae.1111perfume.com/storage/mg5-banner.jpg\" alt=\"MG5-BANNER\" loading=\"lazy\"><br>&nbsp;</p><shortcode>[product-collections title=\"مجموعة المنتجات \" limit=\"8\"][/product-collections]</shortcode><p><img src=\"https://ae.1111perfume.com/storage/womens-perfume-arabic.jpg\" alt=\"WOMENS-PERFUME-ARABIC\" loading=\"lazy\"></p><shortcode>[product-category-products category_id=\"32\" limit=\"8\"][/product-category-products]</shortcode><p><img src=\"https://ae.1111perfume.com/storage/terroni-mens-perfume-arabic.jpg\" alt=\"TERRONI-MENS-PERFUME-ARABIC\" loading=\"lazy\"></p><shortcode>[product-category-products category_id=\"31\" limit=\"8\"][/product-category-products]</shortcode><p><img src=\"https://ae.1111perfume.com/storage/unisex-banner-arabic.jpg\" alt=\"UNISEX-BANNER-ARABIC\" loading=\"lazy\"><br>&nbsp;</p><shortcode>[product-category-products category_id=\"33\" limit=\"8\"][/product-category-products]</shortcode>'),('ar',6,'اتصل بنا',NULL,'<shortcode>[contact-form][/contact-form]</shortcode>'),('ar',7,'من نحن',NULL,'<h3 style=\"background-color:rgb(255,255,255);font-family:Assistant, sans-serif;font-style:normal;text-align:right;word-spacing:0px;\"><strong>معلومات عنا</strong></h3><p style=\"background-color:rgb(255,255,255);color:rgba(18,18,18,0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-weight:400;text-align:right;word-spacing:0px;\"><strong>11:11 Perfume</strong> هي دار عطور فاخرة تأسست بشغف لابتكار عطور استثنائية تأسر الحواس وتجسد الأناقة والرقي والجاذبية الخالدة. وباعتبارنا اسمًا جديدًا في عالم العطور الفاخرة، نفخر بتقديم مجموعتنا الرائعة إلى منطقة دول مجلس التعاون الخليجي - حيث يتم تقدير فن صناعة العطور والاحتفاء به بشدة.</p><p style=\"background-color:rgb(255,255,255);color:rgba(18,18,18,0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-weight:400;text-align:right;word-spacing:0px;\">في <strong>11:11 Perfume</strong> ، نحن متخصصون في صناعة العطور عالية الجودة التي تحكي القصص من خلال الرائحة. ينعكس التزامنا بالجودة في كل زجاجة، حيث نختار بعناية أفضل المكونات من جميع أنحاء العالم، ونمزج بين الفن التقليدي والتقنيات المبتكرة لخلق عطور فريدة لا تُنسى. كل رائحة هي رحلة للحواس، مصممة لإثارة المشاعر وإلهام الثقة وترك انطباع دائم.</p><p style=\"background-color:rgb(255,255,255);color:rgba(18,18,18,0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-weight:400;text-align:right;word-spacing:0px;\">عطورنا ليست مجرد روائح عطرية، بل هي تعبير عن الهوية والثقافة والفخامة. ونظرًا لتفهمنا للأذواق المميزة لعملائنا في دول مجلس التعاون الخليجي، فإننا نسعى جاهدين لتقديم جودة استثنائية وتجربة شخصية تتوافق مع التراث الغني لتقدير العطور في المنطقة.</p><p style=\"background-color:rgb(255,255,255);color:rgba(18,18,18,0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-weight:400;text-align:right;word-spacing:0px;\">سواء كانت رائحة قوية وجريئة أو جوهرًا ناعمًا ورقيقًا، فإن مجموعاتنا تقدم شيئًا يناسب كل شخصية ومناسبة. <strong>11:11 عطر</strong> ، نحن ملتزمون بتقديم تجربة شمية فريدة من نوعها مثلك.</p><p style=\"background-color:rgb(255,255,255);color:rgba(18,18,18,0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-weight:400;margin-bottom:0px;text-align:right;word-spacing:0px;\"><strong>انضم إلينا</strong> في هذه الرحلة المثيرة حيث نعمل على إعادة تعريف العطور الفاخرة في منطقة دول مجلس التعاون الخليجي - حيث التميز هو المعيار ويتم تصنيع كل رائحة بإتقان.</p>'),('ar',8,'سياسة ملفات تعريف الارتباط',NULL,'<h3 style=\"background-color:rgb(255,255,255);font-family:Assistant, sans-serif;font-style:normal;text-align:right;word-spacing:0px;\"><strong>معلومات عنا</strong></h3><p style=\"background-color:rgb(255,255,255);color:rgba(18,18,18,0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-weight:400;text-align:right;word-spacing:0px;\"><strong>11:11 Perfume</strong> هي دار عطور فاخرة تأسست بشغف لابتكار عطور استثنائية تأسر الحواس وتجسد الأناقة والرقي والجاذبية الخالدة. وباعتبارنا اسمًا جديدًا في عالم العطور الفاخرة، نفخر بتقديم مجموعتنا الرائعة إلى منطقة دول مجلس التعاون الخليجي - حيث يتم تقدير فن صناعة العطور والاحتفاء به بشدة.</p><p style=\"background-color:rgb(255,255,255);color:rgba(18,18,18,0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-weight:400;text-align:right;word-spacing:0px;\">في <strong>11:11 Perfume</strong> ، نحن متخصصون في صناعة العطور عالية الجودة التي تحكي القصص من خلال الرائحة. ينعكس التزامنا بالجودة في كل زجاجة، حيث نختار بعناية أفضل المكونات من جميع أنحاء العالم، ونمزج بين الفن التقليدي والتقنيات المبتكرة لخلق عطور فريدة لا تُنسى. كل رائحة هي رحلة للحواس، مصممة لإثارة المشاعر وإلهام الثقة وترك انطباع دائم.</p><p style=\"background-color:rgb(255,255,255);color:rgba(18,18,18,0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-weight:400;text-align:right;word-spacing:0px;\">عطورنا ليست مجرد روائح عطرية، بل هي تعبير عن الهوية والثقافة والفخامة. ونظرًا لتفهمنا للأذواق المميزة لعملائنا في دول مجلس التعاون الخليجي، فإننا نسعى جاهدين لتقديم جودة استثنائية وتجربة شخصية تتوافق مع التراث الغني لتقدير العطور في المنطقة.</p><p style=\"background-color:rgb(255,255,255);color:rgba(18,18,18,0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-weight:400;text-align:right;word-spacing:0px;\">سواء كانت رائحة قوية وجريئة أو جوهرًا ناعمًا ورقيقًا، فإن مجموعاتنا تقدم شيئًا يناسب كل شخصية ومناسبة. <strong>11:11 عطر</strong> ، نحن ملتزمون بتقديم تجربة شمية فريدة من نوعها مثلك.</p><p style=\"background-color:rgb(255,255,255);color:rgba(18,18,18,0.75);font-family:Assistant, sans-serif;font-size:16px;font-style:normal;font-weight:400;margin-bottom:0px;text-align:right;word-spacing:0px;\"><strong>انضم إلينا</strong> في هذه الرحلة المثيرة حيث نعمل على إعادة تعريف العطور الفاخرة في منطقة دول مجلس التعاون الخليجي - حيث التميز هو المعيار ويتم تصنيع كل رائحة بإتقان.</p>'),('ar',10,'المرتجعات والاستبدالات',NULL,'<p class=\"\" style=\"text-align:right;\" data-start=\"78\" data-end=\"95\"><strong data-start=\"78\" data-end=\"95\">سياسة الإرجاع</strong></p><p class=\"\" style=\"text-align:right;\" data-start=\"97\" data-end=\"200\">في 11:11، رضاك هو أولويتنا القصوى. ولضمان تجربة تسوق خالية من القلق، قمنا بتوضيح سياسة الإرجاع التالية:</p><p class=\"\" style=\"text-align:right;\" data-start=\"202\" data-end=\"313\"><strong data-start=\"202\" data-end=\"218\">عينة للتجربة</strong><br>يتم تضمين عينة (تستر) مع كل منتج. يرجى استخدام العينة أولاً للتأكد من أن العطر يلبي توقعاتك.</p><p class=\"\" style=\"text-align:right;\" data-start=\"315\" data-end=\"333\"><strong data-start=\"315\" data-end=\"331\">شروط الإرجاع</strong></p><ul data-start=\"334\" data-end=\"455\"><li class=\"\" data-start=\"334\" data-end=\"389\"><p class=\"\" style=\"text-align:right;\" data-start=\"336\" data-end=\"389\">يجب تقديم طلب الإرجاع خلال 3 أيام من استلام المنتج.</p></li><li class=\"\" data-start=\"390\" data-end=\"455\"><p class=\"\" style=\"text-align:right;\" data-start=\"392\" data-end=\"455\">يجب أن يكون المنتج في حالته الأصلية، ويُمنع فتح الغلاف الخارجي.</p></li></ul><p class=\"\" style=\"text-align:right;\" data-start=\"457\" data-end=\"476\"><strong data-start=\"457\" data-end=\"474\">طريقة الإرجاع</strong></p><ul data-start=\"477\" data-end=\"630\"><li class=\"\" data-start=\"477\" data-end=\"556\"><p class=\"\" style=\"text-align:right;\" data-start=\"479\" data-end=\"556\">تواصل مع فريق خدمة العملاء لدينا خلال فترة الثلاثة أيام لبدء عملية الإرجاع.</p></li><li class=\"\" data-start=\"557\" data-end=\"630\"><p class=\"\" style=\"text-align:right;\" data-start=\"559\" data-end=\"630\">تأكد من تغليف كل من المنتج غير المفتوح والعينة (التستر) بشكل آمن للشحن.</p></li></ul><p class=\"\" style=\"text-align:right;\" data-start=\"632\" data-end=\"653\"><strong data-start=\"632\" data-end=\"651\">عملية الاسترداد</strong></p><ul data-start=\"654\" data-end=\"802\"><li class=\"\" data-start=\"654\" data-end=\"723\"><p class=\"\" style=\"text-align:right;\" data-start=\"656\" data-end=\"723\">بمجرد استلامنا وفحصنا للعناصر المرتجعة، سيتم بدء عملية الاسترداد.</p></li><li class=\"\" data-start=\"724\" data-end=\"802\"><p class=\"\" style=\"text-align:right;\" data-start=\"726\" data-end=\"802\">سيتم إصدار المبلغ المسترد خلال 7 أيام عمل إلى وسيلة الدفع الأصلية المستخدمة.</p></li></ul><p class=\"\" style=\"text-align:right;\" data-start=\"804\" data-end=\"822\"><strong data-start=\"804\" data-end=\"820\">ملاحظات مهمة</strong></p><ul data-start=\"823\" data-end=\"983\"><li class=\"\" data-start=\"823\" data-end=\"907\"><p class=\"\" style=\"text-align:right;\" data-start=\"825\" data-end=\"907\">يجب إرجاع كل من المنتج والعينة معًا وبحالتهما الأصلية حتى تكون مؤهلاً للاسترداد.</p></li><li class=\"\" data-start=\"908\" data-end=\"983\"><p class=\"\" style=\"text-align:right;\" data-start=\"910\" data-end=\"983\">في حال وجود أي علامات تدل على الفتح أو الاستخدام، سيتم رفض عملية الإرجاع.</p></li></ul><p class=\"\" style=\"text-align:right;\" data-start=\"985\" data-end=\"1045\">للمزيد من المساعدة، لا تتردد في التواصل مع فريق الدعم لدينا.</p>'),('ar',12,'سياسة الخصوصية',NULL,'<p style=\"text-align:center;\"><span style=\"font-size:17px;\"><span><strong>سياسة الخصوصية</strong></span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>آخر تحديث: 20 يناير 2025</strong></span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>توضح سياسة الخصوصية هذه كيف تقوم 11:11 Perfume (\"الموقع\"، \"نحن\"، \"لنا\" أو \"خاصتنا\") بجمع واستخدام والإفصاح عن معلوماتك الشخصية عند زيارتك للموقع، استخدامك لخدماتنا، أو قيامك بعملية شراء من 1111perfume.com أو تواصلك معنا بأي شكل فيما يتعلق بالموقع. ولأغراض هذه السياسة، تشير كلمتا \"أنت\" و\"بياناتك\" إلى المستخدم للخدمات، سواء كنت عميلاً، زائرًا للموقع، أو أي فرد آخر قمنا بجمع معلوماته بموجب هذه السياسة.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>يرجى قراءة سياسة الخصوصية هذه بعناية. باستخدامك أو دخولك إلى أي من الخدمات، فإنك توافق على جمع واستخدام والإفصاح عن معلوماتك على النحو الموضح في هذه السياسة. إذا لم توافق على سياسة الخصوصية هذه، فيرجى عدم استخدام أو الوصول إلى أي من الخدمات.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>التغييرات على سياسة الخصوصية هذه</strong> قد نقوم بتحديث سياسة الخصوصية هذه من وقت لآخر، بما في ذلك لتحديث ممارساتنا أو لأسباب تشغيلية، قانونية، أو تنظيمية أخرى. سنقوم بنشر النسخة المعدّلة من سياسة الخصوصية على الموقع، وتحديث تاريخ \"آخر تحديث\"، واتخاذ أي خطوات أخرى يفرضها القانون المعمول به.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>كيف نجمع ونستخدم معلوماتك الشخصية</strong> من أجل تقديم الخدمات، نقوم بجمع معلومات شخصية عنك من عدة مصادر، كما هو موضح أدناه. تختلف أنواع المعلومات التي نجمعها ونستخدمها حسب طريقة تفاعلك معنا.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>بالإضافة إلى الاستخدامات المحددة أدناه، قد نستخدم المعلومات التي نجمعها عنك للتواصل معك، وتقديم أو تحسين الخدمات، والامتثال لأي التزامات قانونية، وتطبيق أي شروط خدمة معمول بها، وحماية أو الدفاع عن الخدمات وحقوقنا وحقوق مستخدمينا أو الآخرين.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>ما المعلومات الشخصية التي نجمعها</strong></span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>تعتمد أنواع المعلومات الشخصية التي نحصل عليها عنك على كيفية تفاعلك مع موقعنا واستخدامك لخدماتنا. عند استخدام مصطلح \"المعلومات الشخصية\"، فإننا نشير إلى المعلومات التي تُعرّفك، أو تتعلق بك، أو تصفك، أو يمكن ربطها بك.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>المعلومات التي نجمعها مباشرة منك</strong></span></span></p><ul><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>تفاصيل الاتصال، مثل: اسمك، عنوانك، رقم هاتفك، وبريدك الإلكتروني.</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>معلومات الطلب، مثل: اسمك، عنوان الفوترة، عنوان الشحن، تأكيد الدفع، البريد الإلكتروني، ورقم الهاتف.</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>معلومات الحساب، مثل: اسم المستخدم، كلمة المرور، أسئلة الأمان، ومعلومات أخرى تُستخدم لأغراض أمان الحساب.</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>معلومات دعم العملاء، مثل: أي معلومات تختار تضمينها عند التواصل معنا، على سبيل المثال، عند إرسال رسالة عبر الخدمات.</span></span></p></li></ul><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>بعض ميزات الخدمات قد تتطلب منك تزويدنا بمعلومات معينة عن نفسك. ويمكنك اختيار عدم تقديم هذه المعلومات، لكن ذلك قد يمنعك من استخدام أو الوصول إلى بعض الميزات.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>المعلومات التي نجمعها حول استخدامك</strong> قد نقوم تلقائيًا بجمع بعض المعلومات المتعلقة بتفاعلك مع الخدمات (\"بيانات الاستخدام\"). وللقيام بذلك، قد نستخدم ملفات تعريف الارتباط (Cookies)، والبيكسل، والتقنيات المماثلة. قد تتضمن بيانات الاستخدام معلومات حول كيفية وصولك إلى موقعنا واستخدامك له ولحسابك، بما في ذلك معلومات الجهاز، معلومات المتصفح، معلومات الاتصال بالشبكة، عنوان بروتوكول الإنترنت (IP)، ومعلومات أخرى تتعلق بتفاعلك مع الخدمات.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>المعلومات التي نحصل عليها من أطراف ثالثة</strong> قد نحصل أيضًا على معلومات عنك من أطراف ثالثة، بما في ذلك من البائعين ومقدمي الخدمات الذين قد يجمعون المعلومات نيابةً عنا، مثل:</span></span></p><ul><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>الشركات التي تدعم موقعنا وخدماتنا، مثل Shopify.</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>معالجي الدفع لدينا، الذين يجمعون معلومات الدفع (مثل رقم الحساب البنكي، أو بطاقة الائتمان أو الخصم، وعنوان الفوترة) لمعالجة مدفوعاتك وتنفيذ طلباتك وتزويدك بالمنتجات أو الخدمات المطلوبة، وذلك بموجب عقدنا معك.</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>عند زيارتك لموقعنا، أو فتحك رسائل البريد الإلكتروني التي نرسلها إليك أو النقر عليها، أو تفاعلك مع خدماتنا أو إعلاناتنا، قد نقوم نحن أو أطراف ثالثة نعمل معهم بجمع معلومات تلقائيًا باستخدام تقنيات تتبع عبر الإنترنت مثل البيكسل، إشارات الويب، حزم مطوري البرمجيات (SDKs)، مكتبات خارجية، وملفات تعريف الارتباط.</span></span></p></li></ul><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>سيتم التعامل مع أي معلومات نحصل عليها من أطراف ثالثة وفقًا لما هو موضح في سياسة الخصوصية هذه. راجع أيضًا قسم <strong>روابط ومواقع الطرف الثالث</strong> أدناه.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>كيف نستخدم معلوماتك الشخصية</strong></span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>توفير المنتجات والخدمات</strong> نستخدم معلوماتك الشخصية لتقديم الخدمات وتنفيذ عقدنا معك، بما يشمل:</span></span></p><ul><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>معالجة المدفوعات،</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>تنفيذ الطلبات،</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>إرسال إشعارات متعلقة بالحساب، المشتريات، المرتجعات، أو غيرها،</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>إنشاء وإدارة الحساب،</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>ترتيب الشحن، وتسهيل عمليات الاسترجاع والاستبدال،</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>توفير الميزات المتعلقة بحسابك.</span></span></p></li></ul><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>قد نحسن تجربتك الشرائية من خلال تمكين Shopify من مطابقة حسابك مع خدمات أخرى يقدمها والتي قد تختار استخدامها. في هذه الحالة، تقوم Shopify بمعالجة معلوماتك وفقًا لسياسة الخصوصية الخاصة بها.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>التسويق والإعلانات</strong> قد نستخدم معلوماتك الشخصية لأغراض تسويقية وترويجية، مثل إرسال رسائل تسويقية وإعلانات عبر البريد الإلكتروني أو الرسائل النصية أو البريد العادي، وكذلك عرض الإعلانات التي تخص المنتجات أو الخدمات. قد يشمل هذا تخصيص الخدمات والإعلانات وفقًا لمعلوماتك.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>الأمان ومنع الاحتيال</strong> نستخدم معلوماتك لاكتشاف، التحقيق، أو اتخاذ إجراءات بشأن أنشطة احتيالية أو غير قانونية أو ضارة. إذا اخترت إنشاء حساب، فأنت مسؤول عن الحفاظ على سرية بيانات الدخول. نوصي بعدم مشاركة اسم المستخدم أو كلمة المرور مع أي طرف ثالث. إذا كنت تشك في اختراق حسابك، يرجى التواصل معنا فورًا.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>التواصل وتحسين الخدمات</strong> نستخدم معلوماتك لتقديم دعم العملاء وتحسين خدماتنا، وذلك في إطار مصالحنا المشروعة للحفاظ على العلاقة معك وتحسين تجربة المستخدم.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>ملفات تعريف الارتباط (Cookies)</strong> مثل العديد من المواقع، نستخدم ملفات تعريف الارتباط في موقعنا. لمزيد من التفاصيل حول الكوكيز التي نستخدمها بخصوص Shopify، يرجى زيارة: </span></span><a><span style=\"font-size:17px;\"><span>https://www.shopify.com/legal/cookies</span></span></a></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>نستخدم الكوكيز لتشغيل وتحسين موقعنا وخدماتنا (بما في ذلك تذكّر إعداداتك)، ولتحليلات الاستخدام، وتخصيص الخدمات والمحتوى. كما نسمح لأطراف ثالثة باستخدام الكوكيز لتخصيص الخدمات والإعلانات.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>معظم المتصفحات تقبل الكوكيز افتراضيًا، ولكن يمكنك ضبط الإعدادات لحذفها أو منعها. ومع ذلك، فإن حظر الكوكيز قد يؤثر سلبًا على تجربتك أو يؤدي إلى عدم عمل بعض الميزات بشكل صحيح.</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span><strong>كيف نكشف عن المعلومات الشخصية</strong> في بعض الحالات، قد نكشف عن معلوماتك الشخصية لأطراف ثالثة لأغراض تنفيذ العقد أو لأسباب قانونية أو تشغيلية. ومن بين هذه الحالات:</span></span></p><ul><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>مع مزودي الخدمات (مثل إدارة تكنولوجيا المعلومات، معالجة المدفوعات، تحليلات البيانات، دعم العملاء، التخزين السحابي، تنفيذ الطلبات، الشحن).</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>مع شركائنا التجاريين وشركاء التسويق لتقديم الخدمات أو الإعلانات. سيقوم هؤلاء باستخدام معلوماتك وفقًا لسياسات الخصوصية الخاصة بهم.</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>عندما تطلب أو توافق على ذلك، مثل شحن المنتجات أو استخدام أدوات تسجيل الدخول عبر الشبكات الاجتماعية.</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>مع الشركات التابعة لنا ضمن مجموعتنا التجارية، في إطار مصلحتنا في إدارة أعمالنا.</span></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>في حال عملية تجارية مثل الدمج أو الإفلاس، أو للامتثال لالتزامات قانونية (مثل الرد على أوامر المحكمة)، أو لفرض الشروط، أو&nbsp;</span></span></p><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><span>لحماية خدماتنا وحقوقنا وحقوق المستخدمين.\"نُفصح عن الفئات التالية من المعلومات الشخصية والمعلومات الشخصية الحساسة الخاصة بالمستخدمين للأغراض الموضحة أعلاه في قسم \'كيف نجمع ونستخدم معلوماتك الشخصية\' و\'كيف نكشف عن المعلومات&nbsp;</span></span></p><figure class=\"table\"><table><tbody><tr><td><p style=\"text-align:center;\"><span style=\"font-size:17px;\">فئات المستلمين</span></p></td><td><p style=\"text-align:center;\"><span style=\"font-size:17px;\">الفئة</span></p></td></tr><tr><td><ul><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">لبائعون والأطراف الثالثة الذين يقدمون خدمات نيابة عنا (مثل مزودي خدمات الإنترنت، ومعالجي الدفع، وشركاء تنفيذ الطلبات، وشركاء دعم العملاء، ومزودي تحليلات البيانات)</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">شركاء الأعمال والتسويق</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">الشركات التابعة</span></p></li></ul></td><td><ul><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">معرفات مثل تفاصيل الاتصال الأساسية وبعض معلومات الطلب والحساب</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">معلومات تجارية مثل بيانات الطلبات، معلومات التسوق، ومعلومات دعم العملاء</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">أنشطة الإنترنت أو الشبكات المماثلة، مثل بيانات الاستخدام</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">بيانات الموقع الجغرافي مثل المواقع التي يتم تحديدها من خلال عنوان IP أو تدابير تقنية أخرى</span></p></li></ul><p style=\"text-align:right;\">&nbsp;</p></td></tr></tbody></table></figure></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>نحن لا نستخدم أو نُفصح عن المعلومات الشخصية الحساسة دون موافقتك أو لأغراض استنتاج خصائص عنك.</strong></span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>روابط ومواقع الطرف الثالث</strong></span><br><span style=\"font-size:17px;\">قد يوفّر موقعنا روابط لمواقع إلكترونية أو منصات أخرى تابعة لأطراف ثالثة. إذا قمت بمتابعة روابط لمواقع غير تابعة لنا أو لا نخضع لسيطرتنا، ينبغي عليك مراجعة سياسات الخصوصية والأمان والشروط والأحكام الخاصة بها. نحن لا نضمن ولسنا مسؤولين عن خصوصية أو أمان تلك المواقع، بما في ذلك دقة أو اكتمال أو موثوقية المعلومات الموجودة عليها. المعلومات التي تقدّمها في أماكن عامة أو شبه عامة، بما في ذلك على منصات التواصل الاجتماعي التابعة لأطراف ثالثة، قد تكون مرئية أيضًا لمستخدمي الخدمات و/أو مستخدمي تلك المنصات بدون قيود على استخدامها من قبلنا أو من قبل أطراف ثالثة. وجودنا لتلك الروابط لا يعني بالضرورة تأييدًا للمحتوى أو لأصحابه أو مشغليه، ما لم يُذكر خلاف ذلك ضمن الخدمات.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>بيانات الأطفال</strong></span><br><span style=\"font-size:17px;\">الخدمات غير موجهة للأطفال، ولا نقوم عن علم بجمع أي معلومات شخصية عن الأطفال. إذا كنت أحد الوالدين أو الأوصياء على طفل قد زودنا بمعلوماته الشخصية، يمكنك التواصل معنا لحذف هذه المعلومات.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">وحتى تاريخ سريان سياسة الخصوصية هذه، نحن لا نمتلك معرفة فعلية بأننا \"نشارك\" أو \"نبيع\" (كما تُعرّفها القوانين المعمول بها) معلومات شخصية لأشخاص دون سن 16 عامًا.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>أمان واحتفاظ بياناتك</strong></span><br><span style=\"font-size:17px;\">يرجى العلم بأنه لا توجد تدابير أمنية مثالية أو غير قابلة للاختراق، ولا يمكننا ضمان \"أمان تام\". بالإضافة إلى ذلك، قد لا تكون المعلومات التي ترسلها إلينا آمنة أثناء النقل. لذلك نوصي بعدم استخدام قنوات غير آمنة لتوصيل المعلومات الحساسة أو السرية.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">مدة احتفاظنا بمعلوماتك الشخصية تعتمد على عدة عوامل، مثل ما إذا كنا بحاجة للمعلومة لإدارة حسابك، تقديم الخدمات، الامتثال للالتزامات القانونية، حل النزاعات، أو تنفيذ العقود والسياسات الأخرى.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>حقوقك</strong></span><br><span style=\"font-size:17px;\">اعتمادًا على مكان إقامتك، قد يكون لك بعض أو كل الحقوق التالية فيما يتعلق بمعلوماتك الشخصية. مع ذلك، قد لا تكون هذه الحقوق مطلقة، وقد تنطبق فقط في ظروف معينة، وفي بعض الحالات، قد نرفض طلبك كما يسمح القانون.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>الحق في الوصول / المعرفة:</strong> قد يكون لك الحق في طلب الوصول إلى المعلومات التي نحتفظ بها عنك، بما في ذلك تفاصيل حول كيفية استخدامها ومشاركتها.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>الحق في الحذف:</strong> قد يكون لك الحق في طلب حذف المعلومات الشخصية التي نحتفظ بها عنك.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>الحق في التصحيح:</strong> قد يكون لك الحق في طلب تصحيح أي معلومات شخصية غير دقيقة نحتفظ بها عنك.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>الحق في نقل البيانات:</strong> قد يكون لك الحق في الحصول على نسخة من معلوماتك الشخصية وطلب نقلها إلى طرف ثالث في بعض الحالات.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>الحق في تقييد المعالجة:</strong> قد يكون لك الحق في مطالبتنا بإيقاف أو تقييد معالجة بياناتك.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>الحق في سحب الموافقة:</strong> إذا كنا نعتمد على موافقتك في معالجة بياناتك، يمكنك سحب تلك الموافقة في أي وقت.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>الحق في الاستئناف:</strong> إذا رفضنا طلبك، قد يكون لك الحق في استئناف قرارنا من خلال الرد على الرفض مباشرة.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>إدارة تفضيلات الاتصال:</strong> قد نرسل إليك رسائل ترويجية، ويمكنك إلغاء الاشتراك منها في أي وقت من خلال رابط \"إلغاء الاشتراك\" الموجود في البريد الإلكتروني. لكننا قد نستمر في إرسال رسائل غير ترويجية مثل تحديثات الحساب أو الطلبات.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">يمكنك ممارسة هذه الحقوق من خلال موقعنا أو بالتواصل معنا عبر بيانات الاتصال أدناه.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">لن نقوم بالتمييز ضدك لممارستك لهذه الحقوق. قد نحتاج لجمع بعض المعلومات للتحقق من هويتك مثل عنوان بريدك الإلكتروني أو تفاصيل حسابك قبل الرد على الطلب. وفقًا للقوانين، يمكنك تعيين وكيل مفوض لتقديم الطلبات نيابةً عنك. وسنطلب من الوكيل إثبات التفويض، وقد نطلب منك التحقق من هويتك مباشرة.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">سنرد على طلبك في الوقت المحدد بموجب القانون المعمول به.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>الشكاوى</strong></span><br><span style=\"font-size:17px;\">إذا كان لديك شكوى بخصوص كيفية معالجتنا لمعلوماتك، يمكنك التواصل معنا باستخدام بيانات الاتصال أدناه. وإذا لم تكن راضيًا عن ردنا، قد يكون لك الحق في الاستئناف أو تقديم شكوى إلى سلطة حماية البيانات المحلية في بلدك.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>المستخدمون الدوليون</strong></span><br><span style=\"font-size:17px;\">يرجى العلم أنه قد يتم نقل معلوماتك الشخصية أو تخزينها أو معالجتها خارج بلد إقامتك. يتم أيضًا معالجة معلوماتك من قبل موظفين ومزودي خدمات خارجيين في هذه البلدان.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\">إذا قمنا بنقل معلوماتك خارج أوروبا، سنعتمد على آليات معترف بها مثل \"البنود التعاقدية القياسية\" الخاصة بالمفوضية الأوروبية أو ما يعادلها من جهات المملكة المتحدة، ما لم يكن البلد المستلم معترفًا به كمناسب من حيث حماية البيانات.</span></p></li><li><p style=\"text-align:right;\"><span style=\"font-size:17px;\"><strong>الاتصال</strong></span><br><span style=\"font-size:17px;\">إذا كان لديك أي أسئلة حول ممارسات الخصوصية الخاصة بنا أو سياسة الخصوصية هذه، أو إذا كنت ترغب في ممارسة أي من حقوقك، يرجى الاتصال بنا عبر البريد الإلكتروني التالي:</span><br><a rel=\"noopener\"><span style=\"font-size:17px;\">care@1111perfume.com</span></a></p></li></ul>'),('ar',15,'عروض خاصة',NULL,'<shortcode>[product-collections title=\"Featured Products\" limit=\"8\"][/product-collections]</shortcode>');
/*!40000 ALTER TABLE `pages_translations` ENABLE KEYS */;
UNLOCK TABLES;

